begin;
    with j as (select * from jsonb_to_recordset($law7v006$[{"code_id":"BK_RF","article_number":"79","version_date":"1998-07-31","article_text":"1. В бюджетах бюджетной системы Российской Федерации,  в том числе в рамках государственных (муниципальных)  программ,  могут предусматриваться бюджетные ассигнования на осуществление бюджетных инвестиций в форме капитальных вложений в объекты государственной (муниципальной)  собственности в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи,  с учетом положений статьи 1791 настоящего Кодекса. (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nОбъекты капитального строительства,  созданные в результате осуществления бюджетных инвестиций,  или объекты недвижимого имущества,  приобретенные в государственную (муниципальную)  собственность в результате осуществления бюджетных инвестиций,  закрепляются в установленном порядке на праве оперативного управления или хозяйственного ведения за государственными (муниципальными)  учреждениями,  государственными (муниципальными)  унитарными предприятиями с последующим увеличением стоимости основных средств,  находящихся на праве оперативного управления у государственных (муниципальных)  учреждений либо на праве оперативного управления или хозяйственного ведения у государственных (муниципальных)  унитарных предприятий,  а также уставного фонда указанных предприятий,  основанных на праве хозяйственного ведения,  либо включаются в состав государственной (муниципальной)  казны. (В редакции Федерального закона от 18.07.2017 № 178-ФЗ)\n\n2. Бюджетные инвестиции в объекты государственной собственности Российской Федерации,  государственной собственности субъекта Российской Федерации,  муниципальной собственности и принятие решений о подготовке и реализации бюджетных инвестиций в указанные объекты осуществляются в порядках,  установленных соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n3. Решения о подготовке и реализации бюджетных инвестиций в объекты государственной собственности Российской Федерации,  находящиеся в оперативном управлении или хозяйственном ведении:\n\nфедеральных государственных учреждений стоимостью 3 миллиарда рублей и более,  а также федеральных государственных загранучреждений и федеральных государственных унитарных предприятий независимо от стоимости принимаются в форме правовых актов  Правительства  Российской Федерации; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 22.12.2020 № 448-ФЗ)\n\nфедеральных государственных учреждений стоимостью менее 3 миллиардов рублей принимаются в установленном Правительством Российской Федерации порядке,  в том числе в случаях,  определенных Правительством Российской Федерации,  в форме правовых актов федеральных органов исполнительной власти или иных организаций,  осуществляющих в соответствии с настоящим Кодексом полномочия главного распорядителя средств федерального бюджета (органов управления государственными внебюджетными фондами Российской Федерации) . (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nВ случае принятия решений,  предусмотренных настоящим пунктом,  в отношении объектов государственной собственности Российской Федерации стоимостью 1, 5 миллиарда рублей и более информация о таких решениях направляется в Государственную Думу и Совет Федерации Федерального Собрания Российской Федерации в порядке,  установленном Правительством Российской Федерации,  в течение 10 дней со дня их принятия. (Дополнение абзацем - Федеральный закон от 22.12.2020 № 448-ФЗ)\n\n31. В случае,  если подготовка обоснования инвестиций для объекта капитального строительства в соответствии с законодательством Российской Федерации является обязательной,  решения о подготовке и реализации бюджетных инвестиций в такие объекты капитального строительства государственной (муниципальной)  собственности принимаются в том числе на основании подготовленного в установленном законодательством Российской Федерации порядке обоснования инвестиций и результатов его технологического и ценового аудита,  а также утвержденного задания на проектирование.\n\nПорядок принятия решений об осуществлении бюджетных инвестиций на подготовку обоснования инвестиций и проведение его технологического и ценового аудита за счет средств федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местного бюджета и порядок осуществления указанных бюджетных инвестиций устанавливаются соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nРешения об осуществлении бюджетных инвестиций на подготовку обоснования инвестиций и проведение его технологического и ценового аудита за счет средств федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации принимаются Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2018 № 222-ФЗ)\n\n4. Органам государственной власти (государственным органам) ,  органам управления государственными внебюджетными фондами,  органам местного самоуправления,  являющимся государственными (муниципальными)  заказчиками,  предоставляется право передать на безвозмездной основе на основании соглашений свои полномочия государственного (муниципального)  заказчика по заключению и исполнению от имени соответствующего публично-правового образования государственных (муниципальных)  контрактов от лица указанных органов при осуществлении бюджетных инвестиций в объекты государственной (муниципальной)  собственности (далее - соглашение о передаче полномочий)  бюджетным и автономным учреждениям,  в отношении которых указанные органы осуществляют функции и полномочия учредителей,  или государственным (муниципальным)  унитарным предприятиям,  в отношении которых указанные органы осуществляют права собственника имущества соответствующего публично-правового образования. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nУсловия передачи полномочий и порядок заключения соглашений о передаче полномочий в отношении объектов государственной собственности Российской Федерации,  государственной собственности субъектов Российской Федерации,  муниципальной собственности устанавливаются соответственно Правительством Российской Федерации,  высшими исполнительными органами субъектов Российской Федерации,  местными администрациями муниципальных образований. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nСоглашение о передаче полномочий может быть заключено в отношении нескольких объектов капитального строительства государственн\n\nс Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\" и принятыми в соответствии с ним иными нормативными правовыми актами Российской Федерации: (В редакции  Федерального закона от 22.06.2024 № 154-ФЗ)\n\n1)  на финансовое обеспечение выполнения бюджетными и автономными учреждениями государственного (муниципального)  задания,  предусмотренного статьей 692 настоящего Кодекса;\n\n2)  на оплату соглашения об оказании государственных (муниципальных)  услуг в социальной сфере,  заключенного по результатам конкурса;\n\n3)  на оплату соглашения о финансовом обеспечении (возмещении)  затрат,  связанных с оказанием государственных (муниципальных)  услуг в социальной сфере в соответствии с социальным сертификатом на получение государственной (муниципальной)  услуги в социальной сфере.\n\n2. Предоставление субсидий,  предусмотренных подпунктами 2 и 3 пункта 1 настоящей статьи,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета осуществляется в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования,  на основании соглашений,  заключенных по результатам отбора исполнителей государственных (муниципальных)  услуг в социальной сфере в соответствии с Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\" и принятыми в соответствии с ним иными нормативными правовыми актами Российской Федерации. (В редакции  федеральных законов от 14.04.2023 № 128-ФЗ,  от 22.06.2024 № 154-ФЗ)\n\n3. Соглашения,  предусмотренные настоящей статьей,  заключаются на срок оказания государственной (муниципальной)  услуги в социальной сфере,  указанный в государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере,  если иной срок не установлен в соответствии с Федеральным законом от 13 июля 2020 года № 189-ФЗ \"О государственном (муниципальном)  социальном заказе на оказание государственных (муниципальных)  услуг в социальной сфере\". (В редакции  Федерального закона от 22.06.2024 № 154-ФЗ)\n\n31. Заключение соглашений о предоставлении субсидий,  предусмотренных подпунктами 2 и 3 пункта 1 настоящей статьи,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета на срок,  превышающий срок действия утвержденных лимитов бюджетных обязательств,  осуществляется в случаях,  предусмотренных соответственно решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации муниципального образования,  принимаемыми в порядке,  определяемом соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (Дополнение пунктом - Федеральный закон от 22.06.2024 № 154-ФЗ)\n\n4. Не использованные в отчетном финансовом году остатки субсидий,  предоставляемых в соответствии с соглашениями,  предусмотренными подпунктами 2 и 3 пункта 1 настоящей статьи,  остаются в распоряжении исполнителей государственных (муниципальных)  услуг в социальной сфере при условии соблюдения ими условий,  установленных такими соглашениями.\n\n(Дополнение статьей - Федеральный закон от 13.07.2020 № 192-ФЗ)","article_title":"Статья 79. Бюджетные инвестиции в объекты государственной (муниципальной)  собственности","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e83f0a585f3ad36701a1ed5769a3a94a578da4f985e61013f538c7d777e971f"},{"code_id":"BK_RF","article_number":"79.1","version_date":"1998-07-31","article_text":"1. Осуществление бюджетных инвестиций из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местного бюджета в объекты государственной (муниципальной)  собственности,  которые не относятся (не могут быть отнесены)  соответственно к государственной собственности Российской Федерации,  государственной собственности субъекта Российской Федерации,  муниципальной собственности,  не допускается.\n\n2. Федеральным законом о федеральном бюджете с учетом положений статьи 1791 настоящего Кодекса могут предусматриваться субсидии бюджетам субъектов Российской Федерации на софинансирование капитальных вложений в объекты государственной собственности субъектов Российской Федерации,  которые осуществляются из бюджетов субъектов Российской Федерации,  или в целях предоставления субсидий местным бюджетам на софинансирование капитальных вложений в объекты муниципальной собственности,  которые осуществляются из местных бюджетов. (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nЗаконом о бюджете субъекта Российской Федерации могут предусматриваться субсидии местным бюджетам на софинансирование капитальных вложений в объекты муниципальной собственности,  которые осуществляются из местных бюджетов.\n\nПредоставление указанных субсидий бюджетам субъектов Российской Федерации (местным бюджетам)  осуществляется в соответствии с актами  Правительства  Российской Федерации (высшего исполнительного органа субъекта Российской Федерации)  и решениями Президента Российской Федерации,  а также за счет бюджетных ассигнований инвестиционного фонда в соответствии со статьей 1792 настоящего Кодекса. (В редакции  федеральных законов от 18.07.2017 № 178-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 628-ФЗ)\n\nПредоставление указанных субсидий бюджетам субъектов Российской Федерации (местным бюджетам)  на софинансирование капитальных вложений в объекты капитального строительства и (или)  приобретения объектов недвижимого имущества,  которые не относятся (не могут быть отнесены)  к государственной собственности субъектов Российской Федерации (муниципальной собственности) ,  не допускается. (Дополнение абзацем - Федеральный закон от 27.12.2018 № 504-ФЗ)\n\n3. (Пункт утратил силу - Федеральный закон от 27.12.2018 № 504-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.12.2013 № 418-ФЗ)","article_title":"Статья 79.1. Особенности осуществления капитальных вложений в объекты государственной (муниципальной)  собственности и предоставления субсидий другим бюджетам бюджетной системы Российской Федерации на осуществление капитальных вложений в объекты государственной (муниципальной)  собственности","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91c51494e3cf4f7725b42e255b25fb730827c2151a907e7b356bbc6095825be1"},{"code_id":"BK_RF","article_number":"8","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nК бюджетным полномочиям субъектов Российской Федерации относятся: (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление порядка составления и рассмотрения проектов бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  утверждения и исполнения бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  осуществления контроля за их исполнением и утверждения отчета об исполнении бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов;\n\nсоставление и рассмотрение проектов бюджета субъекта Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов,  утверждение и исполнение бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  осуществление контроля за их исполнением,  составление и утверждение отчетов об исполнении бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  составление отчетов об исполнении консолидированного бюджета субъекта Российской Федерации;\n\nустановление порядка представления в исполнительные органы субъектов Российской Федерации утвержденных местных бюджетов,  отчетов об исполнении местных бюджетов и иной бюджетной отчетности,  установленной федеральными органами государственной власти; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nустановление и исполнение расходных обязательств субъекта Российской Федерации;\n\nопределение порядка установления и исполнения расходных обязательств муниципальных образований,  подлежащих исполнению за счет субвенций из бюджета субъекта Российской Федерации;\n\nустановление нормативов отчислений доходов в местные бюджеты от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством о налогах и сборах в бюджеты субъектов Российской Федерации; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление нормативов отчислений доходов в бюджеты сельских поселений от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством Российской Федерации о налогах и сборах в бюджеты муниципальных районов,  в случае,  если законами субъекта Российской Федерации и принятыми в соответствии с ними уставом муниципального района и уставами сельских поселений за сельскими поселениями закреплены другие вопросы местного значения из числа вопросов местного значения городских поселений,  решаемых муниципальным районом на территориях сельских поселений; (Дополнение абзацем - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\nопределение законами субъектов Российской Федерации источников доходов бюджетов внутригородских районов,  за исключением случаев,  предусмотренных настоящим Кодексом; (Дополнение абзацем - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\nустановление порядка и условий предоставления межбюджетных трансфертов из бюджета субъекта Российской Федерации;\n\nпредоставление межбюджетных трансфертов из бюджета субъекта Российской Федерации;\n\nустановление общего порядка и условий предоставления межбюджетных трансфертов из местных бюджетов;\n\nосуществление государственных заимствований и предоставление государственных гарантий субъекта Российской Федерации,  предоставление бюджетных кредитов,  управление государственным долгом и государственными активами субъекта Российской Федерации; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление,  детализация и определение порядка применения бюджетной классификации Российской Федерации в части,  относящейся к бюджету субъекта Российской Федерации и бюджетам территориальных государственных внебюджетных фондов; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nвременное осуществление отдельных бюджетных полномочий органов местного самоуправления;\n\nабзац; (Утратил силу - Федеральный закон от 26.07.2019 № 199-ФЗ)\n\nустановление нормативов отчислений доходов в местные бюджеты от отдельных неналоговых доходов,  подлежащих зачислению в бюджеты субъектов Российской Федерации; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nиные бюджетные полномочия,  отнесенные настоящим Кодексом к бюджетным полномочиям органов государственной власти субъектов Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nК бюджетным полномочиям субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя помимо вышеперечисленных бюджетных полномочий относятся: (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nопределение законами указанных субъектов Российской Федерации источников доходов бюджетов внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя. Установленные настоящим Кодексом источники доходов местных бюджетов,  не отнесенные законами субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя к источникам доходов бюджетов внутригородских муниципальных образований,  зачисляются в бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nустановление нормативов отчислений доходов в бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных налогов и (или)  местных налогов и сборов,  подлежащих зачислению в бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя в соответствии с настоящим Кодексом и законодательством о налогах и сборах; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ; от 03.11.2015 № 301-ФЗ)\n\nустановление нормативов отчислений доходов в бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя от неналоговых доходов,  подлежащих зачислению в бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nопределение объема и порядка предоставления межбюджетных трансфертов бюджетам внутригородских муниципальных образований субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 02.08.2019 № 307-ФЗ)\n\nопределение объема,  порядка предоставления и распределения дотаций на выравнивание бюджетной обеспеченности внутригородских муниципальных образований субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nопределение перечня и порядка исполнения расходных обязательств внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  вытекающих из полномочий по вопросам местного значения,  определенных законами субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nопределение порядка ведения реестра расходных обязательств внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n(Часть в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nПоложения,  установленные настоящим Кодексом в отношении субъектов Российской Федерации (органов государственной власти субъектов Российской Федерации) ,  субъектов Российской Федерации - городов федерального значения (в части доходов их бюджетов) ,  бюджетов субъектов Российской Федерации и бюджетов территориальных фондов обязательного медицинского страхования,  распространяются на федеральные территории (органы публичной власти федеральных территорий) ,  за исключением положений,  устанавливающих полномочия субъектов Российской Федерации (органов государственной власти субъектов Российской Федерации) ,  субъектов Российской Федерации - городов федерального значения в отношении муниципальных образований (местных бюджетов) ,  находящихся на их территории. В случае,  если положения настоящего Кодекса содержат указание на закон субъекта Российской Федерации,  применяется нормативный правовой акт представительного органа федеральной территории. (Дополнение частью - Федеральный закон от 11.06.2021 № 195-ФЗ)  (В редакции Федерального закона от 29.11.2021 № 384-ФЗ)","article_title":"Статья 8. Бюджетные полномочия субъектов Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6005cf71b61bc42a76f2db42a0524361a8fe25df6568c97795c1fa6562f0a263"},{"code_id":"BK_RF","article_number":"80","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n1. Предоставление бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями,  влечет возникновение права государственной или муниципальной собственности на эквивалентную часть уставных (складочных)  капиталов указанных юридических лиц,  которое оформляется участием Российской Федерации,  субъектов Российской Федерации и муниципальных образований в уставных (складочных)  капиталах таких юридических лиц в соответствии с гражданским законодательством Российской Федерации. Оформление доли Российской Федерации,  субъекта Российской Федерации,  муниципального образования в уставном (складочном)  капитале,  принадлежащей Российской Федерации,  субъекту Российской Федерации,  муниципальному образованию,  осуществляется в порядке и по ценам,  которые определяются в соответствии с законодательством Российской Федерации. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nПорядок принятия решений о предоставлении бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями,  из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета устанавливается соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией. (Дополнение абзацем - Федеральный закон от 27.12.2019 № 479-ФЗ)  (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nРешения о предоставлении бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями,  в объекты капитального строительства,  находящиеся в собственности указанных юридических лиц,  и (или)  на приобретение ими объектов недвижимого имущества либо в целях предоставления взноса в уставные (складочные)  капиталы дочерних обществ указанных юридических лиц на осуществление капитальных вложений в объекты капитального строительства,  находящиеся в собственности таких дочерних обществ,  и (или)  на приобретение такими дочерними обществами объектов недвижимого имущества из федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета принимаются соответственно в форме правовых актов  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  муниципальных правовых актов местной администрации муниципального образования. (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (В редакции федеральных законов от 28.12.2013 № 418-ФЗ,  от 18.07.2017 № 178-ФЗ,  от 27.12.2019 № 479-ФЗ,  от 29.11.2021 № 384-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nВ случае,  если подготовка обоснования инвестиций для объекта капитального строительства в соответствии с законодательством Российской Федерации является обязательной,  решения,  указанные в абзаце втором настоящего пункта,  в отношении таких объектов капитального строительства принимаются в том числе на основании подготовленного в установленном законодательством Российской Федерации порядке обоснования инвестиций и результатов его технологического и ценового аудита,  а также утвержденного задания на проектирование. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 222-ФЗ)\n\n2. Бюджетные инвестиции из федерального бюджета,  планируемые к предоставлению юридическим лицам,  указанным в пункте 1 настоящей статьи,  утверждаются федеральным законом о федеральном бюджете в качестве отдельного приложения к данному федеральному закону с указанием юридического лица,  объема и цели предоставляемых бюджетных инвестиций,  за исключением бюджетных инвестиций,  источником финансового обеспечения которых являются бюджетные ассигнования резервных фондов Президента Российской Федерации и  Правительства  Российской Федерации,  а также бюджетных инвестиций,  предоставляемых в целях исполнения принятых в соответствии с федеральными законами решений об утвержденном размере капитала,  при внесении изменений в сводную бюджетную роспись в соответствии с абзацем двадцать первым пункта 7 статьи 217 настоящего Кодекса. (В редакции федеральных законов от 18.07.2017 № 178-ФЗ; от 28.11.2018 № 453-ФЗ)\n\n3. Договор между Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации или уполномоченными ими федеральными органами исполнительной власти,  исполнительными органами субъекта Российской Федерации,  а также местной администрацией муниципального образования и юридическим лицом,  указанным в пункте 1 настоящей статьи,  об участии соответственно Российской Федерации,  субъекта Российской Федерации или муниципального образования в собственности субъекта инвестиций оформляется в течение трех месяцев после дня вступления в силу закона (решения)  о бюджете. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nОбязательным условием,  включаемым в договоры о предоставлении бюджетных инвестиций юридическим лицам,  указанным в пункте 1 настоящей статьи,  является запрет приобретения за счет полученных средств иностранной валюты,  за исключением операций,  осуществляемых в соответствии с валютным законодательством Российской Федерации при закупке (поставке)  высокотехнологичного импортного оборудования,  сырья и комплектующих изделий,  а также связанных с достижением целей предоставления бюджетных инвестиций иных операций,  определенных решениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации муниципального образования,  в том числе указанными в абзаце втором пункта 1 настоящей статьи. (В редакции  федеральных законов от 18.07.2017 № 178-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nТребования к договорам,  заключенным в связи с предоставлением бюджетных инвестиций юридическим лицам,  указанным в пункте 1 настоящей статьи,  за счет средств федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета,  устанавливаются соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nОтсутствие оформленных в установленном порядке договоров служит основанием для непредоставления бюджетных инвестиций.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 23-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 80. Предоставление бюджетных инвестиций юридическим лицам,  не являющимся государственными или муниципальными учреждениями и государственными или муниципальными унитарными предприятиями","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61edb50fef2f1b5e07784e9531e1ff54c6207632b0bc1ea718713f986e8bcbed"},{"code_id":"BK_RF","article_number":"81","version_date":"1998-07-31","article_text":"1. В расходной части бюджетов бюджетной системы Российской Федерации (за исключением бюджетов государственных внебюджетных фондов)  предусматривается создание резервных фондов исполнительных органов государственной власти (местных администраций)  - резервного фонда  Правительства  Российской Федерации,  резервных фондов высших исполнительных органов субъектов Российской Федерации,  резервных фондов местных администраций. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n2. В расходной части бюджетов бюджетной системы Российской Федерации запрещается создание резервных фондов законодательных (представительных)  органов и депутатов законодательных (представительных)  органов.\n\n3. Размер резервных фондов исполнительных органов государственной власти (местных администраций)  устанавливается законами (решениями)  о соответствующих бюджетах. (В редакции  Федерального закона от 21.11.2022 № 448-ФЗ)\n\n4. Средства резервных фондов исполнительных органов государственной власти (местных администраций)  направляются на финансовое обеспечение непредвиденных расходов,  в том числе на проведение аварийно-восстановительных работ и иных мероприятий,  связанных с ликвидацией последствий стихийных бедствий и других чрезвычайных ситуаций,  а также на иные мероприятия,  предусмотренные порядком,  указанным в пункте 6 настоящей статьи. (В редакции Федерального закона от 30.11.2016 № 409-ФЗ)\n\n5. Бюджетные ассигнования резервного фонда  Правительства  Российской Федерации,  резервного фонда высшего исполнительного органа субъекта Российской Федерации,  резервного фонда местной администрации,  предусмотренные в составе федерального\n\nразований. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nСоглашение о передаче полномочий может быть заключено в отношении нескольких объектов капитального строительства государственной (муниципальной)  собственности и (или)  объектов недвижимого имущества,  приобретаемых в государственную (муниципальную)  собственность,  и должно содержать в том числе:\n\nцель осуществления бюджетных инвестиций и их объем с разбивкой по годам в отношении каждого объекта капитального строительства или объекта недвижимого имущества с указанием его наименования,  мощности,  сроков строительства (реконструкции,  в том числе с элементами реставрации,  технического перевооружения)  или приобретения,  стоимости объекта,  соответствующих решениям,  указанным в пунктах 2 и 3 настоящей статьи,  а также общего объема капитальных вложений в объект государственной (муниципальной)  собственности,  в том числе объема бюджетных ассигнований,  предусмотренного соответствующему органу,  указанному в абзаце первом настоящего пункта,  как получателю бюджетных средств,  соответствующих решениям,  указанным в пунктах 2 и 3 настоящей статьи. В случае предоставления бюджетных инвестиций из федерального бюджета их объем должен соответствовать объему бюджетных ассигнований на осуществление бюджетных инвестиций,  определенному в соответствии со статьей 1791 настоящего Кодекса; (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nположения,  устанавливающие права и обязанности бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия по заключению и исполнению от имени соответствующего публично-правового образования в лице органа,  указанного в абзаце первом настоящего пункта,  государственных (муниципальных)  контрактов;\n\nответственность бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия за неисполнение или ненадлежащее исполнение переданных им полномочий;\n\nположения,  устанавливающие право органа,  указанного в абзаце первом настоящего пункта,  на проведение проверок соблюдения бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием условий,  установленных заключенным соглашением о передаче полномочий;\n\nположения,  устанавливающие обязанность бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия по ведению бюджетного учета,  составлению и представлению бюджетной отчетности органу,  указанному в абзаце первом настоящего пункта,  как получателя бюджетных средств.\n\nСоглашения о передаче полномочий являются основанием для открытия органам,  указанным в абзаце первом настоящего пункта,  в органах Федерального казначейства (финансовых органах субъектов Российской Федерации и финансовых органах муниципальных образований)  лицевых счетов получателя бюджетных средств по переданным полномочиям для учета операций по осуществлению бюджетных инвестиций в объекты государственной (муниципальной)  собственности.\n\n41. В случаях,  определенных федеральными законами (за исключением федерального закона о федеральном бюджете) ,  иными нормативными правовыми актами о создании публично-правовых компаний,  государственным корпорациям (компаниям) ,  публично-правовым компаниям может предоставляться право на заключение и исполнение от имени Российской Федерации,  субъекта Российской Федерации государственных контрактов от лица органов государственной власти (государственных органов) ,  являющихся государственными заказчиками,  передавших государственным корпорациям (компаниям) ,  публично-правовым компаниям на безвозмездной основе на основании соглашений свои полномочия государственного заказчика при осуществлении бюджетных инвестиций в объекты капитального строительства (за исключением бюджетных инвестиций в целях реконструкции,  в том числе с элементами реставрации,  технического перевооружения указанных объектов) ,  которые будут находиться в государственной собственности,  в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи.\n\nСозданные в результате осуществления бюджетных инвестиций объекты капитального строительства,  указанные в абзаце первом настоящего пункта,  закрепляются в установленном порядке на праве оперативного управления за государственными учреждениями либо на праве оперативного управления или хозяйственного ведения за государственными унитарными предприятиями с последующим увеличением стоимости основных средств,  находящихся на праве оперативного управления у государственных учреждений либо на праве оперативного управления или хозяйственного ведения у государственных унитарных предприятий,  а также увеличением уставного фонда указанных предприятий,  основанных на праве хозяйственного ведения,  в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи.\n\nПолномочия государственного (муниципального)  заказчика могут быть переданы федеральными органами исполнительной власти,  исполнительными органами субъекта Российской Федерации,  органами местного самоуправления,  являющимися государственными (муниципальными)  заказчиками,  юридическим лицам,  акции (доли)  которых принадлежат соответственно Российской Федерации,  субъекту Российской Федерации,  муниципальному образованию,  при осуществлении бюджетных инвестиций в объекты капитального строительства государственной (муниципальной)  собственности с последующей передачей указанных объектов в качестве вклада в уставные (складочные)  капиталы таких юридических лиц в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи. Указанные решения должны содержать информацию о юридических лицах,  которым передаются полномочия государственного (муниципального)  заказчика. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nПередача объектов капитального строительства в качестве вклада в уставные (складочные)  капиталы юридических лиц,  указанных в абзаце третьем настоящего пункта,  влечет возникновение права государственной или муниципальной собственности на эквивалентную часть уставных (складочных)  капиталов указанных юридических лиц,  которое оформляется участием Российской Федерации,  субъектов Российской Федерации и муниципальных образований в уставных (складочных)  капиталах таких юридических лиц в соответствии с гражданским законодательством Российской Федерации. Оформление доли Российской Федерации,  субъекта Российской Федерации,  муниципального образования в уставном (складочном)  капитале,  принадлежащей Российской Федерации,  субъекту Российской Федерации,  муниципальному образованию,  осуществляется в порядке и по ценам,  которые определяются в соответствии с законодательством Российской Федерации.\n\nПри передаче государственным корпорациям (компаниям) ,  публично-правовым компаниям или иным юридическим лицам полномочий,  предусмотренных настоящим пунктом,  на них распространяются положения,  установленные пунктом 4 настоящей статьи для бюджетных и автономных учреждений,  государственных (муниципальных)  унитарных предприятий.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 178-ФЗ)\n\n5. Бюджетные инвестиции в объекты капитального строительства государственной (муниципальной)  собственности могут осуществляться в соответствии с концессионными соглашениями.\n\n6. Не допускается при исполнении соответствующего бюджета предоставление бюджетных инвестиций в объекты государственной (муниципальной)  собственности,  по которым принято решение о предоставлении субсидий на осуществление капитальных вложений в объекты государственной (муниципальной)  собственности,  за исключением случая,  указанного в абзаце втором настоящего пункта. (В редакции Федерального закона от 29.12.2015 № 406-ФЗ)\n\nПри исполнении соответствующего бюджета допускается предоставление бюджетных инвестиций в объекты государственной (муниципальной)  собственности,  указанные в абзаце первом настоящего пункта,  в случае изменения в установленном порядке типа бюджетного или автономного учреждения или организационно-правовой формы государственного (муниципального)  унитарного предприятия,  являющихся получателями субсидий,  предусмотренных статьей 782 настоящего Кодекса,  на казенное учреждение после внесения соответствующих изменений в решение о предоставлении субсидий на осуществление капитальных вложений в указанные объекты с внесением соответствующих изменений в ранее заключенные бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием договоры в части замены стороны договора - бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия на казенное учреждение и вида договора - гражданско-правового договора бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия на государственный (муниципальный)  контракт. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 406-ФЗ)\n\n(Статья в редакции Федерального закона от 28.12.2013 № 418-ФЗ)","article_title":"Статья 81. Резервные фонды исполнительных органов государственной власти (местных администраций)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b5370a4ee5618af53e96837bd96487b4ad305cc1ad3d9b9c64272f6be613820"},{"code_id":"BK_RF","article_number":"81.1","version_date":"1998-07-31","article_text":"1. Законом субъекта Российской Федерации (за исключением закона субъекта Российской Федерации о бюджете субъекта Российской Федерации)  может быть предусмотрено создание Резервного фонда субъекта Российской Федерации.\n\nВ случае создания Резервного фонда субъекта Российской Федерации порядок формирования и использования средств указанного Фонда устанавливается законом субъекта Российской Федерации (за исключением закона субъекта Российской Федерации о бюджете субъекта Российской Федерации) .\n\n2. Резервный фонд субъекта Российской Федерации представляет собой часть средств бюджета субъекта Российской Федерации,  предназначенную для исполнения расходных обязательств субъекта Российской Федерации в случае недостаточности доходов бюджета субъекта Российской Федерации для финансового обеспечения расходных обязательств.\n\n(Дополнение статьей - Федеральный закон от 30.12.2008 № 310-ФЗ)","article_title":"Статья 81.1. Резервный фонд субъекта Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0019d7af3b97d2f5b219c4a26d3cf46a4e10fc990b31bc48eb717737f6ffc8c2"},{"code_id":"BK_RF","article_number":"82","version_date":"1998-07-31","article_text":"1. Федеральным бюджетом на очередной финансовый год и плановый период предусматривается создание резервного фонда Президента Российской Федерации в размере не более 1 процента утвержденных расходов федерального бюджета. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Средства резервного фонда Президента Российской Федерации используются на финансовое обеспечение непредвиденных расходов. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n3. Использование бюджетных ассигнований резервного фонда Президента Российской Федерации осуществляется на основании указов и распоряжений Президента Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n4. Использование бюджетных ассигнований резервного фонда Президента Российской Федерации на проведение выборов,  референдумов,  освещение деятельности Президента Российской Федерации не допускается. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 82. Резервный фонд Президента Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d1aae30ca602184229d5b99df70d6673438af33990c1bc6ef7886f790f3743e"},{"code_id":"BK_RF","article_number":"83","version_date":"1998-07-31","article_text":"1. Если принимается закон либо другой нормативный правовой акт,  предусматривающий увеличение расходных обязательств по существующим видам расходных обязательств или введение новых видов расходных обязательств,  которые до его принятия не исполнялись ни одним публично-правовым образованием,  указанный нормативный правовой акт должен содержать нормы,  определяющие источники и порядок исполнения новых видов расходных обязательств,  в том числе в случае необходимости порядок передачи финансовых ресурсов на новые виды расходных обязательств в соответствующие бюджеты бюджетной системы Российской Федерации.\n\n2. Выделение бюджетных ассигнований на принятие новых видов расходных обязательств или увеличение бюджетных ассигнований на исполнение существующих видов расходных обязательств может осуществляться только с начала очередного финансового года при условии включения соответствующих бюджетных ассигнований в закон (решение)  о бюджете либо в текущем финансовом году после внесения соответствующих изменений в закон (решение)  о бюджете при наличии соответствующих источников дополнительных поступлений в бюджет и (или)  при сокращении бюджетных ассигнований по отдельным статьям расходов бюджета.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Наименование в редакции Федерального закона  от 26.04.2007 № 63-ФЗ)\n\n(Глава в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 83. Осуществление расходов,  не предусмотренных бюджетом","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd26c08348b638cfdb983d663c276f5ac78ff85e2b9fe2f1c387105760793a19"},{"code_id":"BK_RF","article_number":"84","version_date":"1998-07-31","article_text":"1. Расходные обязательства Российской Федерации возникают в результате:\n\nпринятия федеральных законов и (или)  нормативных правовых актов Президента Российской Федерации и  Правительства  Российской Федерации при осуществлении федеральными органами государственной власти полномочий по предметам ведения Российской Федерации и (или)  полномочий по предметам совместного ведения,  не отнесенным в соответствии с Федеральным законом от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\" к полномочиям органов государственной власти субъектов Российской Федерации; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nзаключения Российской Федерацией (от имени Российской Федерации)  договоров (соглашений)  при осуществлении федеральными органами государственной власти полномочий по предметам ведения Российской Федерации и (или)  полномочий по предметам совместного ведения,  не отнесенным в соответствии с Федеральным законом от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\" к полномочиям органов государственной власти субъектов Российской Федерации; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nзаключения от имени Российской Федерации договоров (соглашений)  федеральными казенными учреждениями; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпринятия федеральных законов и (или)  нормативных правовых актов Президента Российской Федерации и  Правительства  Российской Федерации,  предусматривающих предоставление из федерального бюджета межбюджетных трансфертов в формах и порядке,  предусмотренных настоящим Кодексом,  в том числе:\n\nсубвенций бюджетам субъектов Российской Федерации,  бюджетам территориальных фондов обязательного медицинского страхования на исполнение расходных обязательств субъектов Российской Федерации в связи с осуществлением органами государственной власти субъектов Российской Федерации переданных им отдельных государственных полномочий Российской Федерации; (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)\n\nсубвенций бюджетам субъектов Российской Федерации для предоставления субвенций местным бюджетам на исполнение расходных обязательств муниципальных образований в связи с наделением органов местного самоуправления отдельными государственными полномочиями Российской Федерации.\n\n(Пункт в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Расходные обязательства Российской Федерации исполняются за счет собственных доходов и источников финансирования дефицита федерального бюджета. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nВ случаях,  установленных федеральными законами,  расходные обязательства Российской Федерации исполняются за счет средств бюджетов государственных внебюджетных фондов Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n3. Положения федеральных законов и (или)  нормативных правовых актов Президента Российской Федерации и (или)  нормативных правовых актов  Правительства  Российской Федерации,  предусматривающие предоставление субвенций из федерального бюджета (бюджета Федерального фонда обязательного медицинского страхования)  бюджетам субъектов Российской Федерации (бюджетам территориальных фондов обязательного медицинского страхования) ,  должны содержать порядок расчета нормативов для определения общего объема субвенций на исполнение соответствующих расходных обязательств субъектов Российской Федерации (муниципальных образований) . (В редакции федеральных законов от 29.11.2010 № 313-ФЗ; от 07.05.2013 № 104-ФЗ)","article_title":"Статья 84. Расходные обязательства Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe26edf365c37f0b7c5a3665c839df949c6b544813c802f736d28e81a7847cf3"},{"code_id":"BK_RF","article_number":"85","version_date":"1998-07-31","article_text":"1. Расходные обязательства субъекта Российской Федерации возникают в результате:\n\nпринятия законов и (или)  иных нормативных правовых актов субъекта Российской Федерации,  а также заключения субъектом Российской Федерации (от имени субъекта Российской Федерации)  договоров (соглашений)  при осуществлении органами государственной власти субъектов Российской Федерации полномочий по предметам ведения субъектов Российской Федерации,  в том числе соглашений о межрегиональном сотрудничестве для совместного развития инфраструктуры; (В редакции  Федерального закона от 28.12.2022 № 562-ФЗ)\n\nпринятия законов и (или)  иных нормативных правовых актов субъекта Российской Федерации,  а также заключения субъектом Российской Федерации (от имени субъекта Российской Федерации)  договоров (соглашений)  при осуществлении органами государственной власти субъектов Российской Федерации полномочий по предметам совместного ведения,  указанных в частях 1 и 5 статьи 44 Федерального закона от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\"; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nзаключения от имени субъекта Российской Федерации договоров (соглашений)  казенными учреждениями субъекта Российской Федерации; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nпринятия законов и (или)  иных нормативных правовых актов субъекта Российской Федерации,  предусматривающих предоставление из бюджета субъекта Российской Федерации межбюджетных трансфертов в формах и порядке,  предусмотренных настоящим Кодексом,  в том числе субвенций местным бюджетам на исполнение расходных обязательств муниципальных образований в связи с наделением органов местного самоуправления отдельными государственными полномочиями субъектов Российской Федерации;\n\nпринятия законов и (или)  иных нормативных правовых актов органов государственной власти субъектов Российской Федерации при осуществлении органами государственной власти субъектов Российской Федерации переданных им полномочий Российской Федерации.\n\n(Пункт в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Расходные обязательства субъекта Российской Федерации,  указанные в абзацах втором - пятом пункта 1 настоящей статьи,  устанавливаются органами государственной власти субъекта Российской Федерации самостоятельно и исполняются за счет собственных доходов и источников финансирования дефицита бюджета субъекта Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nВ случаях,  установленных федеральными законами,  регулирующими деятельность территориальных государственных внебюджетных фондов,  и (или)  принимаемыми в соответствии с ними законами субъектов Российской Федерации,  расходные обязательства субъекта Российской Федерации могут исполняться за счет средств соответствующих бюджетов территориальных государственных внебюджетных фондов. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n3. Законы субъекта Российской Федерации,  предусматривающие предоставление местным бюджетам субвенций из бюджета субъекта Российской Федерации,  должны содержать порядок расчета нормативов для определения общего объема субвенций на исполнение соответствующих расходных обязательств муниципальных образований. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\n4. Расходные обязательства субъекта Российской Федерации,  указанные в абзаце шестом пункта 1 настоящей статьи,  устанавливаются законами и (или)  иными нормативными правовыми актами органов государственной власти субъекта Российской Федерации в соответствии с федеральными законами и (или)  нормативными правовыми актами Президента Российской Федерации и  Правительства  Российской Федерации и исполняются за счет и в пределах субвенций из федерального бюджета,  предоставляемых бюджетам субъектов Российской Федерации в порядке,  предусмотренном статьей 133 настоящего Кодекса,  а также за счет и в пределах субвенций из бюджета Федерального фонда обязательного медицинского страхования,  предоставляемых бюджетам территориальных фондов обязательного медицинского страхования в порядке,  предусмотренном статьей 1332 настоящего Кодекса. (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)\n\nВ случае,  если в субъекте Российской Федерации превышены нормативы,  используемые в методиках расчета соответствующих субвенций,  финансовое обеспечение дополнительных расходов,  необходимых для полного исполнения указанных расходных обязательств субъекта Российской Федерации,  осуществляется за счет собственных доходов и источников финансирования дефицита бюджета субъекта Российской Федерации.\n\n(Пункт в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n5. Органы государственной власти субъекта Российской Федерации самостоятельно определяют размеры и условия оплаты труда государственных гражданских служащих субъекта Российской Федерации и работников государственных учреждений субъекта Российской Федерации с соблюдением требований,  установленных настоящим Кодексом. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 26.04.2007 № 63-ФЗ)\n\n6. Органы государственной власти субъекта Российской Федерации не вправе устанавливать и исполнять расходные обязательства,  связанные с решением вопросов,  отнесенных к компетенции федеральных органов государственной власти,  за исключением случаев,  установленных федеральными законами.\n\nОрганы государственной власти субъекта Российской Федерации вправе устанавливать и исполнять расходные обязательства,  связанные с решением вопросов,  не отнесенных к компетенции федеральных органов государственной власти,  органов местного самоуправления и не исключенных из компетенции органов государственной власти субъекта Российской Федерации федеральными законами,  законами субъекта Российской Федерации,  только при наличии соответствующих средств бюджета субъекта Российской Федерации (за исключением межбюджетных трансфертов) . (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n7. Ежегодный объем расходов бюджета субъекта Российской Федерации,  являющегося в текущем финансовом году получателем дотаций на выравнивание бюджетной обеспеченности субъектов Российской Федерации,  направляемый на исполнение в очередном финансовом году и каждом году планового периода обязательств,  возникающих при исполнении концессионных соглашений (в размере платы концедента,  капитального гранта) ,  обязательств перед юридическими лицами,  являющимися стороной соглашений о государственно-частном партнерстве (в размере платы публичного партнера,  капитального гранта) ,  обязательств по уплате лизинговых платежей по договорам финансовой аренды (лизинга) ,  не должен превышать 10 процентов утвержденного общего годового объема доходов бюджета субъекта Российской Федерации без учета объема безвозмездных поступлений,  за исключением безвозмездных поступлений из федерального бюджета в целях софинансирования расходных обязательств субъектов Российской Федерации,  возникающих при исполнении указанных концессионных соглашений,  соглашений о государственно-частном партнерстве,  договоров финансовой аренды (лизинга) ,  а также безвозмездных поступлений от публично-правовой компании \"Фонд развития территорий\". (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\nВ случае,  если в бюджете субъекта Российской Федерации,  являющегося в текущем финансовом году получателем дотаций на выравнивание бюджетной обеспеченности субъектов Российской Федерации,  на очередной финансовый год и плановый период объем расходов,  указанных в абзаце первом настоящего пункта,  превысил 10 процентов утвержденного общего годового объема доходов бюджета субъекта Российской Федерации без учета объема безвозмездных поступлений,  за исключением безвозмездных поступлений из федерального бюджета в целях софинансирования расходных обязательств субъектов Российской Федерации,  возникающих при исполнении указанных концессионных соглашений,  соглашений о государственно-частном партнерстве,  договоров финансовой аренды (лизинга) ,  а также безвозмездных поступлений от публично-правовой компании \"Фонд развития территорий\",  субъект Российской Федерации вправе осуществлять только принятые до 1 января очередного года обязательства,  возникшие при исполнении концессионных соглашений,  обязательства перед юридическими лицами,  являющимися стороной соглашений о государственно-частном партнерстве,  а также обязательства по уплате лизинговых платежей по договорам финансовой аренды (лизинга)  без принятия новых соответствующих обязательств.\n\nОграничение,  установленное абзацем первым настоящего пункта,  не распространяется на концессионные соглашения,  соглашения о государственно-частном партнерстве,  договоры финансовой аренды (лизинга) ,  заключенные до 1 января 2025 года. (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\nОбъем расходов бюджета субъекта Российской Федерации,  являющегося в отчетном финансовом году получателем дотаций на выравнивание бюджетной обеспеченности субъектов Российской Федерации,  направленный на исполнение в отчетном финансовом году обязательств,  возникающих при исполнении концессионных соглашений (в размере платы концедента,  капитального гранта) ,  обязательств перед юридическими лицами,  являющимися стороной соглашений о государственно-частном партнерстве (в размере платы публичного партнера,  капитального гранта) ,  а также обязательств по уплате лизинговых платежей по договорам финансовой аренды (лизинга) ,  по данным годового отчета об исполнении бюджета субъекта Российской Федерации должен соответствовать ограничению,  установленному абзацем первым настоящего пункта. (В редакции  Федерального закона от 21.04.2025 № 84-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 13.07.2024 № 177-ФЗ)","article_title":"Статья 85. Расходные обязательства субъекта Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c4abb188f9aa100a19aa434014123d3e521842f1e29b68eaba7ab1082892c00"},{"code_id":"BK_RF","article_number":"86","version_date":"1998-07-31","article_text":"1. Расходные обязательства муниципального образования возникают в результате:\n\nпринятия муниципальных правовых актов по вопросам местного значения и иным вопросам,  которые в соответствии с федеральными законами вправе решать органы местного самоуправления,  а также заключения муниципальным образованием (от имени муниципального образования)  договоров (соглашений)  по данным вопросам,  в том числе соглашений о межмуниципальном сотрудничестве для совместного развития инфраструктуры,  стороной которых является городской округ; (В редакции  федеральных законов от 26.04.2007 № 63-ФЗ,  от 28.12.2022 № 562-ФЗ)\n\nпринятия муниципальных правовых актов при осуществлении органами местного самоуправления переданных им отдельных государственных полномочий; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nзаключения от имени муниципального образования договоров (соглашений)  муниципальными казенными учреждениями. (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)  (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n2. Расходные обязательства муниципального образования,  указанные в абзацах втором и четвертом пункта 1 настоящей статьи,  устанавливаются органами местного самоуправления самостоятельно и исполняются за счет собственных доходов и источников финансирования\n\nфонда  Правительства  Российской Федерации,  резервного фонда высшего исполнительного органа субъекта Российской Федерации,  резервного фонда местной администрации,  предусмотренные в составе федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета,  используются по решению соответственно  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n6. Порядок использования бюджетных ассигнований резервного фонда  Правительства  Российской Федерации,  резервного фонда высшего исполнительного органа субъекта Российской Федерации,  резервного фонда местной администрации,  предусмотренных в составе федерального бюджета,  бюджета субъекта Российской Федерации,  местного бюджета,  устанавливается соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n7. Отчет об использовании бюджетных ассигнований резервного фонда  Правительства  Российской Федерации прилагается к годовому отчету об исполнении федерального бюджета,  отчет об использовании бюджетных ассигнований резервных фондов высших исполнительных органов субъектов Российской Федерации,  резервных фондов местных администраций прилагается к годовому отчету об исполнении соответствующего бюджета. (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 86. Расходные обязательства муниципального образования","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"923334a0ab271ab2e5123725f355e5d7f177d9f497b436ebf7cbe7b9ef4c4911"},{"code_id":"BK_RF","article_number":"9","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n1. К бюджетным полномочиям муниципальных образований относятся: (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление порядка составления и рассмотрения проекта местного бюджета,  утверждения и исполнения местного бюджета,  осуществления контроля за его исполнением и утверждения отчета об исполнении местного бюджета;\n\nсоставление и рассмотрение проекта местного бюджета,  утверждение и исполнение местного бюджета,  осуществление контроля за его исполнением,  составление и утверждение отчета об исполнении местного бюджета;\n\nустановление и исполнение расходных обязательств муниципального образования;\n\nопределение порядка предоставления межбюджетных трансфертов из местных бюджетов,  предоставление межбюджетных трансфертов из местных бюджетов;\n\nосуществление муниципальных заимствований,  предоставление муниципальных гарантий,  предоставление бюджетных кредитов,  управление муниципальным долгом и управление муниципальными активами; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление,  детализация и определение порядка применения бюджетной классификации Российской Федерации в части,  относящейся к местному бюджету; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 26.07.2019 № 199-ФЗ)\n\nиные бюджетные полномочия,  отнесенные настоящим Кодексом к бюджетным полномочиям органов местного самоуправления. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. К бюджетным полномочиям муниципальных районов помимо полномочий,  перечисленных в пункте 1 настоящей статьи,  относятся: (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты городских,  сельских поселений от федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных и местных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом,  законодательством о налогах и сборах и (или)  законами субъектов Российской Федерации в бюджеты муниципальных районов; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 29.11.2014 № 383-ФЗ)\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты городских,  сельских поселений от отдельных неналоговых доходов,  подлежащих зачислению в бюджеты муниципальных районов; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nустановление порядка и условий предоставления межбюджетных трансфертов из бюджета муниципального района бюджетам городских,  сельских поселений,  предоставление межбюджетных трансфертов из бюджета муниципального района бюджетам городских,  сельских поселений;\n\nабзац; (Утратил силу - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nсоставление отчета об исполнении консолидированного бюджета муниципального района.\n\n21. К бюджетным полномочиям городских округов с внутригородским делением помимо полномочий,  перечисленных в пункте 1 настоящей статьи,  относятся:\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты внутригородских районов от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  региональных и (или)  местных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом,  законодательством Российской Федерации о налогах и сборах и (или)  законами субъектов Российской Федерации в бюджеты городских округов с внутригородским делением;\n\nустановление в соответствии с федеральными законами и законами субъектов Российской Федерации нормативов отчислений доходов в бюджеты внутригородских районов от отдельных неналоговых доходов,  подлежащих зачислению в бюджеты городских округов с внутригородским делением; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 307-ФЗ)\n\nустановление порядка и условий предоставления межбюджетных трансфертов из бюджета городского округа с внутригородским делением бюджетам внутригородских районов,  предоставление межбюджетных трансфертов из бюджета городского округа с внутригородским делением бюджетам внутригородских районов;\n\nсоставление отчета об исполнении консолидированного бюджета городского округа с внутригородским делением.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n3. Органы местного самоуправления городских,  сельских поселений,  внутригородских районов,  муниципальных районов (в отношении населенных пунктов,  других территорий,  расположенных на межселенных территориях) ,  муниципальных округов,  городских округов,  внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя наряду с полномочиями,  перечисленными в пункте 1 настоящей статьи,  в соответствии с настоящим Кодексом осуществляют также бюджетные полномочия по установлению порядка составления,  утверждения и исполнения смет доходов и расходов отдельных населенных пунктов,  других территорий,  не являющихся муниципальными образованиями,  входящих в состав территории городского,  сельского поселения,  внутригородского района,  муниципального района (в отношении населенного пункта,  другой территории,  расположенных на межселенной территории) ,  муниципального округа,  городского округа,  внутригородского муниципального образования города федерального значения Москвы,  Санкт-Петербурга или Севастополя. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\n4. (Дополнение пунктом - Федеральный закон от 26.04.2007 № 63-ФЗ)  (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nЧАСТЬ ВТОРАЯ. БЮДЖЕТНАЯ СИСТЕМА РОССИЙСКОЙ ФЕДЕРАЦИИ","article_title":"Статья 9. Бюджетные полномочия муниципальных образований","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"889de84ccddf44420c7e2d672cd3bfe8fa677ccea4046204512d0631aa36c281"},{"code_id":"GK_RF","article_number":"1","version_date":"1994-11-30","article_text":"1. Гражданское законодательство основывается на признании равенства участников регулируемых им отношений, неприкосновенности собственности, свободы договора, недопустимости произвольного вмешательства кого-либо в частные дела, необходимости беспрепятственного осуществления гражданских прав, обеспечения восстановления нарушенных прав, их судебной защиты.\n\n2. Граждане (физические лица) и юридические лица приобретают и осуществляют свои гражданские права своей волей и в своем интересе. Они свободны в установлении своих прав и обязанностей на основе договора и в определении любых не противоречащих законодательству условий договора.\n\nГражданские права могут быть ограничены на основании федерального закона и только в той мере, в какой это необходимо в целях защиты основ конституционного строя, нравственности, здоровья, прав и законных интересов других лиц, обеспечения обороны страны и безопасности государства.\n\n3. При установлении, осуществлении и защите гражданских прав и при исполнении гражданских обязанностей участники гражданских правоотношений должны действовать добросовестно.\n\n4. Никто не вправе извлекать преимущество из своего незаконного или недобросовестного поведения.\n\n5. Товары, услуги и финансовые средства свободно перемещаются на всей территории Российской Федерации.\n\nОграничения перемещения товаров и услуг могут вводиться в соответствии с федеральным законом, если это необходимо для обеспечения безопасности, защиты жизни и здоровья людей, охраны природы и культурных ценностей.\n\n(Статья в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 1. Основные начала гражданского законодательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87cc5a719d9c13b3de94146528372d31d30c064c7c13c76ae26351f75030121d"},{"code_id":"GK_RF","article_number":"10","version_date":"1994-11-30","article_text":"1. Не допускаются осуществление гражданских прав исключительно с намерением причинить вред другому лицу, действия в обход закона с противоправной целью, а также иное заведомо недобросовестное осуществление гражданских прав (злоупотребление правом).\n\nНе допускается использование гражданских прав в целях ограничения конкуренции, а также злоупотребление доминирующим положением на рынке.\n\n2. В случае несоблюдения требований, предусмотренных пунктом 1 настоящей статьи, суд, арбитражный суд или третейский суд с учетом характера и последствий допущенного злоупотребления отказывает лицу в защите принадлежащего ему права полностью или частично, а также применяет иные меры, предусмотренные законом.\n\n3. В случае, если злоупотребление правом выражается в совершении действий в обход закона с противоправной целью, последствия, предусмотренные пунктом 2 настоящей статьи, применяются, поскольку иные последствия таких действий не установлены настоящим Кодексом.\n\n4. Если злоупотребление правом повлекло нарушение права другого лица, такое лицо вправе требовать возмещения причиненных этим убытков.\n\n5. Добросовестность участников гражданских правоотношений и разумность их действий предполагаются.\n\n(Статья в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 10. Пределы осуществления гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82f26f8d6f4d34176e8729f9650f2d7524b5388c48b77d248e14119aa5800b86"},{"code_id":"GK_RF","article_number":"101","version_date":"1994-11-30","article_text":"Уменьшение уставного капитала общества допускается после уведомления всех его кредиторов в порядке, определяемом законом об акционерных обществах. Права кредиторов в случае уменьшения уставного капитала общества или снижения стоимости его чистых активов определяются законом об акционерных обществах. (В редакции Федерального закона от 27.12.2009 № 352-ФЗ)\n\nПрава и обязанности кредиторов кредитных организаций и некредитных финансовых организаций, созданных в организационно-правовой форме акционерного общества, определяются также законами, регулирующими деятельность таких организаций. (Дополнение абзацем - Федеральный закон от 08.07.1999 № 138-ФЗ) (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 101. Уменьшение уставного капитала акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7f6f6d368969fe29b3bb4aaf484728fdf195103c97fe8bb2fd9b6f6b54281b1"},{"code_id":"GK_RF","article_number":"102","version_date":"1994-11-30","article_text":"до полной оплаты всего уставного капитала;\n\nесли стоимость чистых активов акционерного общества меньше его уставного капитала и резервного фонда либо станет меньше их размера в результате выплаты дивидендов;\n\nв иных случаях, предусмотренных законом об акционерных обществах.  (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 102. Ограничения на выпуск ценных бумаг и выплату дивидендов акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6d1dd038c10a736d04b6c9c2b48be5c9816c82b6d67a084a94d49ceefef4d2db"},{"code_id":"GK_RF","article_number":"103","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 103. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96fba3f60695998f879bdbc9750258cddcd5503f2d24a982065cb51d24eabbc0"},{"code_id":"GK_RF","article_number":"104","version_date":"1994-11-30","article_text":"1. Акционерное общество может быть реорганизовано или ликвидировано добровольно по решению общего собрания акционеров.\n\nИные основания и порядок реорганизации и ликвидации акционерного общества определяются законом. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n(Подпараграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Дополнение подпараграфом - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 104. Реорганизация и ликвидация акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2862a8eb72507cf5695b12bc5eaef2443cd7883117ac9a06301954fa97b9ad6"},{"code_id":"GK_RF","article_number":"106.1","version_date":"1994-11-30","article_text":"1. Производственным кооперативом (артелью) признается добровольное объединение граждан на основе членства для совместной производственной или иной хозяйственной деятельности (производство, переработка, сбыт промышленной, сельскохозяйственной и иной продукции, выполнение работ, торговля, бытовое обслуживание, оказание других услуг), основанной на их личном трудовом и ином участии и объединении его членами (участниками) имущественных паевых взносов. Законом и уставом производственного кооператива может быть предусмотрено участие в его деятельности юридических лиц. Производственный кооператив является корпоративной коммерческой организацией.\n\n2. Члены производственного кооператива несут по обязательствам кооператива субсидиарную ответственность в размерах и в порядке, которые предусмотрены законом о производственных кооперативах и уставом кооператива.","article_title":"Статья 106.1. Понятие производственного кооператива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13cefb020327b1f0a350aa89610e69e4f0d5e912228a0ed383e2751ce9446dd4"},{"code_id":"GK_RF","article_number":"106.2","version_date":"1994-11-30","article_text":"1. Учредительным документом производственного кооператива является его устав, утвержденный общим собранием его членов.\n\n2. Устав производственного кооператива должен содержать сведения о фирменном наименовании кооператива и месте его нахождения, условия о размере паевых взносов членов кооператива, составе и порядке внесения паевых взносов членами кооператива и об их ответственности за нарушение обязательства по внесению паевых взносов, о характере и порядке трудового участия его членов в деятельности кооператива и об их ответственности за нарушение обязанности принимать личное трудовое участие в деятельности кооператива, о порядке распределения прибыли и убытков кооператива, размере и об условиях субсидиарной ответственности его членов по обязательствам кооператива, о составе и компетенции органов кооператива и порядке принятия ими решений, в том числе по вопросам, решения по которым принимаются единогласно или квалифицированным большинством голосов.\n\n3. Фирменное наименование производственного кооператива должно содержать его наименование и слова \"производственный кооператив\" или слово \"артель\".\n\n4. Число членов кооператива не должно быть менее пяти.","article_title":"Статья 106.2. Создание производственного кооператива и его устав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cdaee1b3b4d4caf906a5219e6a9af51d6f882e121acaa625e2b9fc46c4c1f40"},{"code_id":"GK_RF","article_number":"106.3","version_date":"1994-11-30","article_text":"1. Имущество, находящееся в собственности производственного кооператива, делится на паи его членов в соответствии с уставом кооператива.\n\nУставом кооператива может быть установлено, что определенная часть принадлежащего кооперативу имущества составляет неделимые фонды, используемые на цели, определяемые уставом.\n\nРешение об образовании неделимых фондов принимается членами кооператива единогласно, если иное не предусмотрено уставом кооператива.\n\n2. Член производственного кооператива обязан внести к моменту регистрации кооператива не менее десяти процентов паевого взноса, а остальную часть в течение года с момента государственной регистрации кооператива.\n\n3. Прибыль производственного кооператива распределяется между его членами в соответствии с их трудовым участием, если иной порядок не предусмотрен законом о производственных кооперативах и уставом кооператива.\n\nВ таком же порядке распределяется имущество, оставшееся после ликвидации кооператива и удовлетворения требований его кредиторов.","article_title":"Статья 106.3. Имущество производственного кооператива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e24ca2bc796d130af3e09d454d9d164e2ac49d2427557ef4a885d9b9f93eb080"},{"code_id":"GK_RF","article_number":"106.4","version_date":"1994-11-30","article_text":"1. Исполнительными органами производственного кооператива являются председатель и правление кооператива, если его образование предусмотрено законом или уставом кооператива.\n\n2. Членами правления производственного кооператива и председателем кооператива могут быть только члены кооператива.\n\n3. Член производственного кооператива имеет один голос при принятии решений общим собранием.","article_title":"Статья 106.4. Особенности управления в производственном кооперативе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8fabd1b5b4f2b12b192ffa19797b8eed1d548e51eabf6db9b3a02f9f7e1bee80"},{"code_id":"GK_RF","article_number":"106.5","version_date":"1994-11-30","article_text":"1. Член производственного кооператива по своему усмотрению вправе выйти из кооператива. В этом случае ему должна быть выплачена стоимость пая или должно быть выдано имущество, стоимость которого соответствует стоимости его пая, а также должны быть произведены другие выплаты, предусмотренные уставом кооператива.\n\nВыплата стоимости пая или выдача д\n\nругого имущества выходящему члену кооператива производится по окончании финансового года и утверждении бухгалтерской (финансовой) отчетности кооператива, если иное не предусмотрено уставом кооператива.\n\n2. Член производственного кооператива может быть исключен из кооператива по решению общего собрания в случае неисполнения или ненадлежащего исполнения обязанностей, возложенных на него уставом кооператива, а также в других случаях, предусмотренных законом и уставом кооператива.\n\nЧлен правления кооператива может быть исключен из кооператива по решению общего собрания в связи с членством в аналогичном кооперативе.\n\nЧлен кооператива, исключенный из него, имеет право на получение пая и других выплат, предусмотренных уставом кооператива, в соответствии с пунктом 1 настоящей статьи.\n\n3. Член производственного кооператива вправе передать свой пай или его часть другому члену кооператива, если иное не предусмотрено законом и уставом кооператива.\n\nПередача пая или его части гражданину, не являющемуся членом кооператива, допускается с согласия общего собрания членов кооператива. В этом случае другие члены кооператива пользуются преимущественным правом покупки такого пая или его части.\n\n4. В случае смерти члена производственного кооператива его наследники могут быть приняты в члены кооператива, если иное не предусмотрено уставом кооператива. В противном случае кооператив выплачивает наследникам стоимость пая умершего члена кооператива.\n\n5. Обращение взыскания на пай члена производственного кооператива по долгам члена кооператива допускается лишь при недостатке иного его имущества для покрытия таких долгов в порядке, установленном законом и уставом кооператива. Взыскание по долгам члена кооператива не может быть обращено на неделимые фонды кооператива.","article_title":"Статья 106.5. Прекращение членства в производственном кооперативе и переход пая","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93168bf7a28378628566e02cf64f31797b35e239edcfde5b0e2b2eb3f1267fac"},{"code_id":"GK_RF","article_number":"106.6","version_date":"1994-11-30","article_text":"Производственный кооператив по решению его членов, принятому единогласно, может преобразоваться в хозяйственное товарищество или общество.\n\n§ 3. (Статьи 107 - 112)\n\n(Параграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 106.6. Преобразование производственного кооператива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63b6f892e31ff26e12eda91be9d7d8fedbb48712295e13f055a704858bfa4fd0"},{"code_id":"GK_RF","article_number":"113","version_date":"1994-11-30","article_text":"1. Унитарным предприятием признается коммерческая организация, не наделенная правом собственности на закрепленное за ней собственником имущество. Имущество унитарного предприятия является неделимым и не может быть распределено по вкладам (долям, паям), в том числе между работниками предприятия.\n\nВ организационно-правовой форме унитарных предприятий действуют государственные и муниципальные предприятия.\n\nВ случаях и в порядке, которые предусмотрены законом о государственных и муниципальных унитарных предприятиях, на базе государственного или муниципального имущества может быть создано унитарное казенное предприятие (казенное предприятие).\n\n2. Имущество государственного или муниципального унитарного предприятия находится в государственной или муниципальной собственности и принадлежит такому предприятию на праве хозяйственного ведения или оперативного управления.\n\nПрава унитарного предприятия на закрепленное за ним имущество определяются в соответствии с настоящим Кодексом и законом о государственных и муниципальных унитарных предприятиях.\n\n3. Учредительным документом унитарного предприятия является его устав, утверждаемый уполномоченным государственным органом или органом местного самоуправления, если иное не предусмотрено законом.\n\nУстав унитарного предприятия должен содержать сведения о его фирменном наименовании и месте его нахождения, предмете и целях его деятельности. Устав унитарного предприятия, не являющегося казенным, должен содержать также сведения о размере уставного фонда унитарного предприятия.\n\n4. Фирменное наименование унитарного предприятия должно содержать указание на собственника его имущества. Фирменное наименование казенного предприятия, кроме того, должно содержать указание на то, что такое предприятие является казенным.\n\n5. Органом унитарного предприятия является руководитель предприятия, который назначается уполномоченным собственником органом, если иное не предусмотрено законом, и ему подотчетен.\n\n6. Унитарное предприятие отвечает по своим обязательствам всем принадлежащим ему имуществом.\n\nУнитарное предприятие не несет ответственность по обязательствам собственника его имущества.\n\nСобственник имущества унитарного предприятия, за исключением собственника имущества казенного предприятия, не отвечает по обязательствам своего унитарного предприятия. Собственник имущества казенного предприятия несет субсидиарную ответственность по обязательствам такого предприятия при недостаточности его имущества.\n\n7. Правовое положение унитарных предприятий определяется настоящим Кодексом и законом о государственных и муниципальных унитарных предприятиях.\n\n8. Унитарное предприятие может быть реорганизовано в соответствии с законом о государственных и муниципальных унитарных предприятиях и законами о приватизации.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 113. Основные положения об унитарном предприятии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64416a4b85492b5fba6d9e235f8662c015102d8f214fb39aedd5f05b71039b4b"},{"code_id":"GK_RF","article_number":"114","version_date":"1994-11-30","article_text":"1. Унитарное предприятие создается от имени публично-правового образования (статья 125) решением уполномоченного на то государственного органа или органа местного самоуправления.\n\n2. Минимальный размер уставного фонда унитарного предприятия определяется законом о государственных и муниципальных унитарных предприятиях.\n\n3. Порядок формирования уставного фонда унитарного предприятия устанавливается законом о государственных и муниципальных унитарных предприятиях.\n\n4. Если по окончании финансового года стоимость чистых активов унитарного предприятия окажется меньше размера уставного фонда, орган, уполномоченный создавать такие предприятия, обязан произвести в установленном порядке уменьшение уставного фонда. Если стоимость чистых активов становится меньше размера, определенного законом, унитарное предприятие может быть ликвидировано по решению суда.\n\n5. В случае принятия решения об уменьшении уставного фонда унитарное предприятие обязано уведомить об этом в письменной форме своих кредиторов.\n\nКредитор унитарного предприятия вправе потребовать прекращения или досрочного исполнения обязательства, должником по которому является это предприятие, и возмещения убытков.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 114. Создание унитарного предприятия и его уставный фонд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8b7bd310edd84570c2977339abe058bd63c00eac0b1a1d8a8ffdbd790edba52"},{"code_id":"GK_RF","article_number":"115","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n§ 5. (Статьи 116 - 123)\n\n(Параграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Дополнение параграфом - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n1. Общие положения о некоммерческих корпоративных организациях","article_title":"Статья 115. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0797a989744fc6ef43b83508d881d02fb0fe421cbc2fa9a613759b8c6f69e8cd"},{"code_id":"GK_RF","article_number":"12","version_date":"1994-11-30","article_text":"Защита гражданских прав осуществляется путем:\n\nпризнания права;\n\nвосстановления положения, существовавшего до нарушения права, и пресечения действий, нарушающих право или создающих угрозу его нарушения;\n\nпризнания оспоримой сделки недействительной и применения последствий ее недействительности, применения последствий недействительности ничтожной сделки;\n\nпризнания недействительным решения собрания; (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\nпризнания недействительным акта государственного органа или органа местного самоуправления;\n\nсамозащиты права;\n\nприсуждения к исполнению обязанности в натуре;\n\nвозмещения убытков;\n\nвзыскания неустойки;\n\nкомпенсации морального вреда;\n\nпрекращения или изменения правоотношения;\n\nнеприменения судом акта государственного органа или органа местного самоуправления, противоречащего закону;\n\nиными способами, предусмотренными законом.","article_title":"Статья 12. Способы защиты гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0042545226f597f1345caa2658dc7a81e0e520fa8b19c2a6a8f046f9b64f7ee9"},{"code_id":"GK_RF","article_number":"123.1","version_date":"1994-11-30","article_text":"1. Некоммерческими корпоративными организациями признаются юридические лица, которые не преследуют извлечение прибыли в качестве основной цели своей деятельности и не распределяют полученную прибыль между участниками (пункт 1 статьи 50 и статья 651), учредители (участники) которых приобретают право участия (членства) в них и формируют их высший орган в соответствии с пунктом 1 статьи 653 настоящего Кодекса.\n\n2. Потребительский кооператив","article_title":"Статья 123.1. Основные положения о некоммерческих корпоративных организациях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c627f35ba05fc0f00d53ab5f10bf9e916b14e9d304c0a0eaf47d85fb97c64556"},{"code_id":"GK_RF","article_number":"123.10","version_date":"1994-11-30","article_text":"1. К исключительной компетенции высшего органа ассоциации (союза) наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относится также принятие решений о порядке определения размера и способа уплаты членских взносов, о дополнительных имущественных взносах членов ассоциации (союза) в ее имущество и о размере их субсидиарной ответственности по обязательствам ассоциации (союза), если такая ответственность предусмотрена законом или уставом.\n\n2. В ассоциации (союзе) образуется единоличный исполнительный орган (председатель, президент и т.п.) и могут образовываться постоянно действующие коллегиальные исполнительные органы (совет, правление, президиум и т.п.).\n\nПо решению высшего органа ассоциации (союза) полномочия органа ассоциации (союза) могут быть досрочно прекращены в случаях грубого нарушения этим органом своих обязанностей, обнаружившейся неспособности к надлежащему ведению дел или при наличии иных серьезных оснований.","article_title":"Статья 123.10. Особенности управления в ассоциации (союзе)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"613a2f8606a79d8b5d5b3e91acf83e229bb1a0ea9dad41f9e4c14d1eba621252"},{"code_id":"GK_RF","article_number":"123.11","version_date":"1994-11-30","article_text":"1. Член ассоциации (союза) осуществляет корпоративные права, предусмотренные пунктом 1 статьи 652 настоящего Кодекса, в порядке, установленном в соответствии с законом уставом ассоциации (союза). Он также вправе на равных начала\n\nх с другими членами ассоциации (союза) безвозмездно, если иное не предусмотрено законом, пользоваться оказываемыми ею услугами.\n\nЧлен ассоциации (союза) вправе выйти из нее по своему усмотрению в любое время.\n\n2. Члены ассоциации (союза) наряду с обязанностями, предусмотренными для участников корпорации пунктом 4 статьи 652 настоящего Кодекса, также обязаны уплачивать предусмотренные уставом членские взносы и по решению высшего органа ассоциации (союза) вносить дополнительные имущественные взносы в имущество ассоциации (союза).\n\nЧлен ассоциации (союза) может быть исключен из нее в случаях и в порядке, которые установлены в соответствии с законом уставом ассоциации (союза).\n\n3. Членство в ассоциации (союзе) неотчуждаемо. Последствия прекращения членства в ассоциации (союзе) устанавливаются законом и (или) ее уставом.","article_title":"Статья 123.11. Права и обязанности члена ассоциации (союза)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fbb7cdf2ffb826c839d54d56d23cf0ae75f25b830ecccf9a5c98f661b12d301"},{"code_id":"GK_RF","article_number":"123.13","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 24.07.2023 № 351-ФЗ)","article_title":"Статья 123.13. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd4cbf9cf97c77feea238cec2aabfc0a007ff534dc9873839ddcd91264224d97"},{"code_id":"GK_RF","article_number":"123.14","version_date":"1994-11-30","article_text":"1. К исключительной компетенции высшего органа товарищества собственников недвижимости наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относится также принятие решений об установлении размера обязательных платежей и взносов членов товарищества.\n\n2. В товариществе собственников недвижимости создаются единоличный исполнительный орган (председатель) и постоянно действующий коллегиальный исполнительный орган (правление).\n\nПо решению высшего органа товарищества собственников недвижимости (пункт 1 статьи 653) полномочия постоянно действующих органов товарищества могут быть досрочно прекращены в случаях грубого нарушения ими своих обязанностей, обнаружившейся неспособности к надлежащему ведению дел или при наличии иных серьезных оснований.","article_title":"Статья 123.14. Особенности управления в товариществе собственников недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4117f87d0b43309c05529ebcdb850f7a10912954e8fdc76318a5bdf1e2a707f"},{"code_id":"GK_RF","article_number":"123.15","version_date":"1994-11-30","article_text":"1. Казачьими обществами признаются внесенные в государственный реестр казачьих обществ в Российской Федерации объединения граждан, созданные в целях сохранения традиционных образа жизни, хозяйствования и культуры российского казачества, а также в иных целях, предусмотренных Федеральным законом от 5 декабря 2005 года № 154-ФЗ \"О государственной службе российского казачества\", добровольно принявших на себя в порядке, установленном законом, обязательства по несению государственной или иной службы.\n\n2. Казачье общество по решению его членов может быть преобразовано в ассоциацию (союз) или автономную некоммерческую организацию.\n\n3. Положения настоящего Кодекса о некоммерческих организациях применяются к казачьим обществам, внесенным в государственный реестр казачьих обществ в Российской Федерации, если иное не установлено Федеральным законом от 5 декабря 2005 года № 154-ФЗ \"О государственной службе российского казачества\".","article_title":"Статья 123.15. Казачье общество, внесенное в государственный реестр казачьих обществ в Российской Федерации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9254eda9c834afb91667afbb43762d6157752e8ee480fff0ad3c2b3bc0fbde7c"},{"code_id":"GK_RF","article_number":"123.16","version_date":"1994-11-30","article_text":"1. Общинами коренных малочисленных народов Российской Федерации признаются добровольные объединения граждан, относящихся к коренным малочисленным народам Российской Федерации и объединившихся по кровнородственному и (или) территориально-соседскому признаку в целях защиты исконной среды обитания, сохранения и развития традиционных образа жизни, хозяйствования, промыслов и культуры.\n\n2. Члены общины коренных малочисленных народов Российской Федерации имеют право на получение части ее имущества или компенсации стоимости такой части при выходе из общины или ее ликвидации в порядке, установленном законом.\n\n3. Община коренных малочисленных народов Российской Федерации по решению ее членов может быть преобразована в ассоциацию (союз) или автономную некоммерческую организацию.\n\n4. Положения настоящего Кодекса о некоммерческих организациях применяются к общинам коренных малочисленных народов Российской Федерации, если иное не установлено законом.\n\n(Дополнение подпараграфом - Федеральный закон от 13.07.2015 № 268-ФЗ)","article_title":"Статья 123.16. Община коренных малочисленных народов Российской Федерации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27d8b8946dd80d324cd036d7833ae871b261483a6c5f48355fdea386ecbe3088"},{"code_id":"GK_RF","article_number":"123.16-1","version_date":"1994-11-30","article_text":"1. Адвокатскими палатами признаются некоммерческие организации, основанные на обязательном членстве и созданные в виде адвокатской палаты субъекта Российской Федерации или Федеральной палаты адвокатов Российской Федерации для реализации целей, предусмотренных законодательством об адвокатской деятельности и адвокатуре.\n\n2. Адвокатская палата субъекта Российской Федерации является некоммерческой организацией, основанной на обязательном членстве всех адвокатов одного субъекта Российской Федерации.\n\n3. Федеральная палата адвокатов Российской Федерации является некоммерческой организацией, объединяющей адвокатские палаты субъектов Российской Федерации на основе обязательного членства.\n\n4. Особенности создания, правового положения и деятельности адвокатских палат субъектов Российской Федерации и Федеральной палаты адвокатов Российской Федерации определяются законодательством об адвокатской деятельности и адвокатуре.\n\n(Дополнение подпараграфом - Федеральный закон от 13.07.2015 № 268-ФЗ)","article_title":"Статья 123.16-1. Адвокатские палаты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a59ad3726f3a57469c793f0b9b11dbca04f084ec2b861740db40e4d8da60eaa"},{"code_id":"GK_RF","article_number":"123.16-2","version_date":"1994-11-30","article_text":"1. Адвокатскими образованиями, являющимися юридическими лицами, признаются некоммерческие организации, созданные в соответствии с законодательством об адвокатской деятельности и адвокатуре в целях осуществления адвокатами адвокатской деятельности.\n\n2. Адвокатские образования, являющиеся юридическими лицами, создаются в виде коллегии адвокатов, адвокатского бюро или юридической консультации.\n\n3. Особенности создания, правового положения и деятельности адвокатских образований, являющихся юридическими лицами, определяются законодательством об адвокатской деятельности и адвокатуре.\n\n(Дополнение подпараграфом - Федеральный закон от 07.02.2017 № 12-ФЗ)","article_title":"Статья 123.16-2. Адвокатские образования, являющиеся юридическими лицами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ad801c5b0422ce8e1cbabe229b8e1c090f2627aaba737fb85c6832528702ba1"},{"code_id":"GK_RF","article_number":"123.16-3","version_date":"1994-11-30","article_text":"1. Нотариальными палатами признаются некоммерческие организации, которые представляют собой профессиональные объединения, основанные на обязательном членстве, и созданы в виде нотариальной палаты субъекта Российской Федерации или Федеральной нотариальной палаты для реализации целей, предусмотренных законодательством о нотариате.\n\n2. Нотариальная палата субъекта Российской Федерации является некоммерческой организацией, представляющей собой профессиональное объединение, основанное на обязательном членстве нотариусов, занимающихся частной практикой.\n\n3. Федеральная нотариальная палата является некоммерческой организацией, представляющей собой профессиональное объединение нотариальных палат субъектов Российской Федерации, основанное на их обязательном членстве.\n\n4. Особенности создания, правового положения и деятельности нотариальных палат субъектов Российской Федерации и Федеральной нотариальной палаты определяются законодательством о нотариате.\n\n(Дополнение параграфом - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n1. Общественно полезные фонды\n\n(Наименование в редакции Федерального закона от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.16-3. Нотариальные палаты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"464eb90637c0a06dc536bcd263592bc7e5fd4b9ff59bfb37338de22fa8b171ba"},{"code_id":"GK_RF","article_number":"123.17","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.17. Основные положения об общественно полезном фонде","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe5558663054b58a3bf000c6fc4ef8902427b4c07d7b55bb8dde007924e80b5f"},{"code_id":"GK_RF","article_number":"123.18","version_date":"1994-11-30","article_text":"1. Имущество, переданное фонду его учредителями (учредителем), является собственностью фонда. Учредители фонда не имеют имущественных прав в отношении созданного ими фонда и не отвечают по его обязательствам, а фонд не отвечает по обязательствам своих учредителей.\n\n2. Фонд использует имущество для целей, определенных в его уставе.\n\nЕжегодно фонд обязан опубликовывать отчеты об использовании своего имущества.","article_title":"Статья 123.18. Имущество фонда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2323157dffededc0213007889ace3d56720dfcfcdf7111cdeaebb71cf5a77386"},{"code_id":"GK_RF","article_number":"123.19","version_date":"1994-11-30","article_text":"определение приоритетных направлений деятельности фонда, принципов образования и использования его имущества;\n\nобразование других органов фонда и досрочное прекращение их полномочий;\n\nутверждение годовых отчетов и годовой бухгалтерской (финансовой) отчетности фонда;\n\nпринятие решений о создании фондом хозяйственных обществ и (или) об участии в них фонда, за исключением случаев, когда уставом фонда принятие решений по указанным вопросам отнесено к компетенции иных коллегиальных органов фонда; (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\nпринятие решений о создании филиалов и (или) об открытии представительств фонда;\n\nизменение устава фонда, если эта возможность предусмотрена уставом;\n\nодобрение совершаемых фондом сделок в случаях, предусмотренных законом.\n\nЗаконом или уставом фонда к исключительной компетенции высшего коллегиального органа фонда может быть отнесено принятие решений по иным вопросам.\n\nК компетенции единоличного исполнительного и (или) коллегиальных органов фонда относится решение вопросов, не входящих в исключительную компетенцию высшего коллегиального органа фонда. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 123.19. Управление фондом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ba8c0913ac74197a98b016d0615106bee5878c9e78a00d0438b6bceda9bf91b"},{"code_id":"GK_RF","article_number":"123.2","version_date":"1994-11-30","article_text":"Наименование потребительского кооператива должно содержать указание на основную цель его деятельности, а также слово \"кооператив\". Наименование общества взаимного страхования должно содержать слова \"потребительское общество\".","article_title":"Статья 123.2. Основные положения о потребительском кооперативе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f83e3b3a784701ce361cb5c4755a9243495e5a5649a276be76da4b8233d3d50"},{"code_id":"GK_RF","article_number":"123.20","version_date":"1994-11-30","article_text":"1. Устав фонда может быть изменен высшим коллегиальным органом фонда, если уставом не предусмотрена возможность его изменения по решению учредителя.\n\nУстав фонда может быть изменен решением суда, принятым по заявлению органов фонда или государственного органа, уполномоченного осуществлять надзор за деятельностью фонда, в случае, если сохранение устава фонда в неизменном виде влечет последствия, которые было невозможно предвидеть при учреждении фонда, а высший коллегиальный орган фонда или учредитель фонда не изменяет его устав.\n\n2. Фонд может быть ликвидирован только на основании решения суда, принятого по заявлению заинтересованных лиц, в случае, если:\n\n1) имущества фонда недостаточно для осуществления его целей и вероятность получения необходимого имущества нереальна;\n\n2) цели фонда не могут быть достигнуты, а необходимые изменения целей фонда не могут быть произведены;\n\n3) фонд в своей деятельности уклоняется от целей, предусмотренных уставом;\n\n4) в других случаях, предусмотренных законом.\n\n3. В случае ликвидации фонда его имущество, оставшееся после удовлетворения требований кредиторов, направляется на цели, указанные в уставе фонда, за исключением случаев, если законом предусмотрен возврат такого имущества учредителям фонда.","article_title":"Статья 123.20. Изменение устава и ликвидация фонда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c395fbf26a262368a5a9259091497e35db0e7637c06b8b177b3865a1b37b7c9"},{"code_id":"GK_RF","article_number":"123.20-1","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2017 № 259-ФЗ) (Утратила силу  - Федеральный закон от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.20-1. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e64c0dc3284fd40b547595aba12b1366ede64ab854788f0cab6b5d658e6f3d7"},{"code_id":"GK_RF","article_number":"123.20-2","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2017 № 259-ФЗ) (Утратила силу  - Федеральный закон от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.20-2. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e64c0dc3284fd40b547595aba12b1366ede64ab854788f0cab6b5d658e6f3d7"},{"code_id":"GK_RF","article_number":"123.20-3","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2017 № 259-ФЗ) (Утратила силу  - Федеральный закон от 01.07.2021 № 287-ФЗ)\n\n11. Личные фонды\n\n(Дополнение подпараграфом - Федеральный закон от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.20-3. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8a6c18d3f3cdd0ce2a5b920ae5669d010fce9239b14a505069a11e9219fcb7b"},{"code_id":"GK_RF","article_number":"123.20-4","version_date":"1994-11-30","article_text":"Учредитель личного фонда вправе предусмотреть в уставе созданного при его жизни личного фонда, что после его смерти такой личный фонд продолжает свою деятельность в соответствии с утвержденным учредителем уставом и условиями управления, при этом такой личный фонд не может быть после смерти его учредителя ликвидирован по решению его органов.\n\nЗамена учредителя личного фонда не допускается. При создании личных фондов не допускается соучредительство нескольких лиц, за исключением случаев, если учредителями личного фонда являются супруги, передающие личному фонду общее имущество (статья 256).\n\nСтоимость имущества, передаваемого личному фонду (за исключением наследственного фонда) его учредителем при создании личного фонда, не может быть менее ста миллионов рублей, при этом стоимость этого имущества определяется на основании оценки его рыночной стоимости.\n\nУчредитель личного фонда вправе утвердить условия управления личным фондом и иные внутренние документы личного фонда, обязательные для всех органов личного фонда.\n\nУстав личного фонда и условия управления личным фондом подлежат нотариальному удостоверению.\n\nЕсли иное не установлено настоящим Кодексом или уставом личного фонда, информация о содержании условий управления личным фондом и содержании иных внутренних документов личного фонда не подлежит раскрытию и является конфиденциальной.\n\nЕсли иное не предусмотрено уставом личного фонда, устав личного фонда, условия управления личным фондом и иные внутренние документы личного фонда при жизни учредителя фонда могут быть им изменены. После смерти учредит\n\nеля личного фонда утвержденные учредителем при его жизни устав личного фонда, условия управления личным фондом и иные внутренние документы личного фонда не могут быть изменены, за исключением изменения на основании решения суда по требованию любого органа личного фонда в случаях, если управление таким фондом на прежних условиях стало невозможно по обстоятельствам, возникновение которых при создании такого фонда нельзя было предполагать. (В редакции  Федерального закона от 08.08.2024 № 237-ФЗ)\n\nУстав наследственного фонда и условия управления наследственным фондом не могут быть изменены после создания наследственного фонда, за исключением изменения на основании решения суда по требованию любого органа наследственного фонда в случаях, если управление наследственным фондом на прежних условиях стало невозможно по обстоятельствам, возникновение которых при создании наследственного фонда нельзя было предполагать, а также в случае, если будет установлено, что выгодоприобретатель наследственного фонда является недостойным наследником (статья 1117), если только это обстоятельство не было известно в момент создания наследственного фонда.\n\n10. Реорганизация личного фонда (за исключением наследственного фонда) допускается в форме слияния, присоединения, разделения, выделения при условии, что в результате такой реорганизации образуются личный фонд или личные фонды, созданные тем же учредителем. При жизни учредителя личного фонда допускается также преобразование личного фонда в общественно полезный фонд по решению учредителя.\n\nРеорганизация личного фонда после смерти его учредителя не допускается, за исключением преобразования личного фонда в общественно полезный фонд в случаях, предусмотренных условиями управления личным фондом и пунктом 6 статьи 12320-5 настоящего Кодекса.\n\n11. Ликвидация личного фонда осуществляется по решению суда:\n\n1) в порядке и по основаниям, предусмотренным подпунктами 1 - 4 пункта 3 статьи 61 настоящего Кодекса, а также по иску уполномоченного государственного органа в случае осуществления личным фондом деятельности, указанной в законодательстве Российской Федерации об иностранных агентах; (В редакции  Федерального закона от 08.08.2024 № 237-ФЗ)\n\n2) по требованию единоличного исполнительного органа личного фонда в связи с наступлением срока, до истечения которого создавался личный фонд;\n\n3) по требованию единоличного исполнительного органа личного фонда в связи с наступлением указанных в условиях управления личным фондом обстоятельств;\n\n4) по требованию выгодоприобретателя личного фонда в случае невозможности формирования органов личного фонда (отсутствие кворума в коллегиальных органах, отсутствие единоличного исполнительного органа);\n\n5) по требованию единоличного исполнительного органа личного фонда в связи с невозможностью на протяжении трех лет, если иной срок не предусмотрен уставом личного фонда, выполнить предусмотренные учредителем личного фонда условия, в соответствии с которыми подлежат определению выгодоприобретатели личного фонда.\n\nОставшееся после ликвидации личного фонда имущество подлежит передаче выгодоприобретателям личного фонда соразмерно объему их прав на получение имущества или дохода от деятельности личного фонда, если условиями управления личным фондом не предусмотрены иные правила распределения оставшегося имущества, в том числе его передача лицам, не являющимся выгодоприобретателями. При отсутствии возможности определить лиц, которым подлежит передаче оставшееся после ликвидации личного фонда имущество, такое имущество подлежит передаче в собственность учредителя (учредителей) личного фонда, а если к этому моменту брак между учредителями, передавшими фонду общее имущество, расторгнут, - в общую долевую собственность учредителей, доли которых в передаваемом им имуществе признаются равными, если иное не установлено соглашением между ними или решением суда. При отсутствии возможности определить лиц, которым подлежит передаче оставшееся после ликвидации наследственного фонда имущество, такое имущество подлежит передаче в соответствии с решением суда в собственность Российской Федерации. (В редакции  Федерального закона от 08.08.2024 № 237-ФЗ)\n\n12. Отчет об использовании имущества личного фонда не подлежит опубликованию, за исключением случаев, предусмотренных условиями управления личным фондом.","article_title":"Статья 123.20-4. Основные положения о личном фонде","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"270d119f925487035f39e711afe564bbd4176135809f8af72f4e1c0ddb5012c4"},{"code_id":"GK_RF","article_number":"123.20-5","version_date":"1994-11-30","article_text":"1. Условия управления личным фондом могут включать в себя положения о передаче определенным лицам (выгодоприобретателям личного фонда) или отдельным категориям лиц из неопределенного круга лиц (далее - отдельные категории лиц) всего имущества личного фонда или его части, в том числе при наступлении обстоятельств, относительно которых неизвестно, наступят они или нет.\n\n2. Условиями управления личным фондом может быть предусмотрено, что выгодоприобретатели личного фонда или отдельные категории лиц, которым подлежит передаче имущество личного фонда, определяются органами личного фонда в соответствии с условиями управления личным фондом.\n\n3. Порядок передачи выгодоприобретателям личного фонда или отдельным категориям лиц всего имущества личного фонда или его части, в том числе доходов от деятельности личного фонда, должен быть определен условиями управления личным фондом путем указания на вид и размер передаваемого имущества или порядок определения вида и размера имущества, в том числе имущественного права (например, права пользования имуществом, права на оплату работ, услуг, оказываемых третьими лицами выгодоприобретателям личного фонда или отдельным категориям лиц), срок или периодичность передачи имущества, а также на обстоятельства, при наступлении которых осуществляется такая передача.\n\n4. Выгодоприобретателями личного фонда могут быть любые участники регулируемых гражданским законодательством отношений, за исключением коммерческих юридических лиц. Учредитель личного фонда не может быть выгодоприобретателем личного фонда, если иное не предусмотрено уставом этого фонда.\n\n5. Выгодоприобретатель личного фонда вправе потребовать от личного фонда, а выгодоприобретатель наследственного фонда вправе потребовать от нотариуса или наследственного фонда ознакомить их с той частью условий управления личным фондом, в которой содержатся порядок определения и назначения органов личного фонда, положения о передаче этому выгодоприобретателю всего или части имущества личного фонда, а также описание обстоятельств, при наступлении которых осуществляется такая передача.\n\n6. Не позднее шести месяцев со дня смерти гражданина, учредившего личный фонд при жизни, если условия управления этим фондом после смерти учредителя предусматривают исключительно положения о передаче отдельным категориям лиц из неопределенного круга лиц всего имущества личного фонда или его части, такой фонд подлежит преобразованию в общественно полезный фонд (статья 12317), при этом устав личного фонда, условия управления личным фондом и иные внутренние документы личного фонда, утвержденные его учредителем, не подлежат изменению, а в едином государственном реестре юридических лиц отражаются сведения о новом наименовании этого фонда и об изменении его организационно-правовой формы.","article_title":"Статья 123.20-5. Условия управления личным фондом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd62cbad7c0ce64a12517727c2f7b62936ae4720258c1864b0bc6009d357588e"},{"code_id":"GK_RF","article_number":"123.20-6","version_date":"1994-11-30","article_text":"1. Выгодоприобретатель личного фонда имеет право на получение имущества в соответствии с условиями управления личным фондом, а также иные права, предусмотренные настоящим Кодексом.\n\nПрава выгодоприобретателя личного фонда не могут переходить к другим лицам, в том числе в случае универсального правопреемства, за исключением случаев преобразования выгодоприобретателя - юридического лица, если условиями управления личным фондом не предусмотрено прекращение прав такого выгодоприобретателя при его преобразовании. На права выгодоприобретателя личного фонда, в том числе выгодоприобретателя наследственного фонда, не может быть обращено взыскание по обязательствам такого выгодоприобретателя. Сделки, совершенные с нарушением этих правил, являются ничтожными.\n\n2. Права гражданина-выгодоприобретателя наследственного фонда не переходят по наследству. Права выгодоприобретателя - юридического лица наследственного фонда прекращаются в случае реорганизации выгодоприобретателя - юридического лица, за исключением случая преобразования, если условиями управления наследственным фондом не предусмотрено прекращение прав такого выгодоприобретателя при его преобразовании.\n\nПосле смерти гражданина-выгодоприобретателя или ликвидации выгодоприобретателя - юридического лица, а также в случае заявленного наследственному фонду в нотариальной форме отказа выгодоприобретателя наследственного фонда от права на получение имущества новые выгодоприобретатели наследственного фонда определяются в соответствии с условиями управления наследственным фондом, в частности, они могут быть определены путем подназначения.\n\n3. В случаях, предусмотренных уставом личного фонда, выгодоприобретатель вправе запрашивать и получать у личного фонда информацию о деятельности личного фонда.\n\n4. Выгодоприобретатель личного фонда вправе потребовать проведения аудита деятельности личного фонда выбранным им аудитором. В случае проведения такого аудита оплата услуг аудитора осуществляется за счет выгодоприобретателя личного фонда, по требованию которого он проводится. Расходы выгодоприобретателя личного фонда на оплату услуг аудитора могут быть ему возмещены по решению попечительского совета за счет средств такого фонда.\n\n5. В случае нарушения условий управления личным фондом, повлекшего возникновение у выгодоприобретателя личного фонда убытков, последний вправе потребовать их возмещения, если это право предусмотрено уставом личного фонда.\n\n6. Выгодоприобретатель не отвечает по обязательствам личного фонда, а личный фонд не отвечает по обязательствам выгодоприобретателя.","article_title":"Статья 123.20-6. Права выгодоприобретателя личного фонда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27341143b96ce0cbed139f1e2c9bcd297a30c3dfab8d701821dc1006c3884ad7"},{"code_id":"GK_RF","article_number":"123.20-7","version_date":"1994-11-30","article_text":"После смерти гражданина, учредившего личный фонд при жизни, органы личного фонда формируются и изменяются в соответствии с уставом и условиями управления этого фонда, при этом лица, входящие в состав органов личного фонда или имеющие право войти в состав органов этого фонда, а также выгодоприобретатели этого фонда вправе требовать формирования и изменения органов личного фонда в соответствии с его уставом и условиями управления личным фондом. Уставом личного фонда и условиями управления личным фондом может быть предусмотрен порядок определения членов коллегиальных органов личного фонда и лица, осуществляющего полномочия единоличного исполнительного органа личного фонда, в случае их выбытия, в том числе предусмотрено подназначение указанных лиц из определенного списка.\n\nВыгодоприобретатель наследственного фонда не может выступать в качестве единоличного исполнительного органа наследственного фонда или члена коллегиального исполнительного органа наследственного фонда.\n\nУставом личного фонда может быть также предусмотрено создание надзорного органа личного фонда, полномочия которого состоят в осуществлении надзора за деятельностью органов личного фонда, в согласовании совершения личным фондом определенных в уставе юридически значимых действий и (или) в принятии решения о досрочном прекращении полномочий единоличного исполнительного органа личного фонда, нарушившего свою обязанность действовать добросовестно или разумно в интересах личного фонда и (или) его выгодоприобретателей, и о назначении временного единоличного исполнительного органа личного фонда.","article_title":"Статья 123.20-7. Управление личным фондом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"49ddf47c99b235d7faf0de5e963e8c32745b0a1cff81173fc0cf201013c9548c"},{"code_id":"GK_RF","article_number":"123.20-8","version_date":"1994-11-30","article_text":"1. После смерти гражданина, который предусмотрел в своем завещании создание наследственного фонда, такой наследственный фонд подлежит созданию по заявлению, направляемому в уполномоченный государственный орган нотариусом, ведущим наследственное дело, с приложением к заявлению составленного при жизни указанного гражданина его решения об учреждении наследственного фонда и утвержденного этим гражданином устава фонда и после его создания призывается к наследованию по завещанию в порядке, предусмотренном разделом V настоящего Кодекса.\n\nНаследственный фонд может быть создан на основании решения суда по требованию душеприказчика или выгодоприобретателя наследственного фонда в случае неисполнения нотариусом обязанности по созданию наследственного фонда.\n\nНотариус, ведущий наследственное дело, обязан направить в уполномоченный государственный орган заявление о государственной регистрации наследственного фонда не позднее трех рабочих дней со дня открытия наследственного дела после смерти гражданина, который предусмотрел в своем завещании создание наследственного фонда. Наследственный фонд не подлежит регистрации по истечении одного года со дня открытия наследства.\n\nДействия нотариуса по созданию наследственного фонда могут быть оспорены выгодоприобретателями наследственного фонда, душеприказчиком или наследниками, если нотариусом нарушены содержащиеся в завещании или решении об учреждении наследственного фонда распоряжения наследодателя относительно создания наследственного фонда и условий управления им.\n\n2. При создании наследственного фонда нотариус, получивший от наследственного фонда заявление о принятии наследства, обязан выдать такому фонду свидетельство о праве на наследство в срок, указанный в решении об учреждении наследственного фонда, но не позднее срока, предусмотренного статьей 1154 настоящего Кодекса. В случае неисполнения нотариусом указанных обязанностей наследственный фонд вправе обжаловать бездействие нотариуса.\n\n3. До направления нотариусом указанного в абзаце третьем пункта 1 настоящей статьи заявления о государственной регистрации наследственного фонда в уполномоченный государственный орган нотариус предлагает лицам, указанным в решении об учреждении наследственного фонда, или лицам, которые могут быть определены в порядке, установленном решением об учреждении наследственного фонда, войти в состав органов наследственного фонда. При согласии указанных лиц войти в состав органов наследственного фонда нотариус направляет сведения о них в уполномоченный государственный орган.\n\nВ случае отказа лица, указанного в решении об учреждении наследственного фонда, войти в состав органов наследственного фонда и невозможности сформировать органы наследственного фонда в соответствии с решением об учреждении наследственного фонда нотариус не вправе направлять в уполномоченный государственный орган заявление о создании наследственного фонда.\n\n4. Замена членов коллегиальных органов наследственного фонда и лица, осуществляющего полномочия единоличного исполнительного органа наследственного фонда, осуществляется в порядке, предусмотренном уставом наследственного фонда. Уставом наследственного фонда может быть предусмотрен порядок определения членов коллегиальных органов наследственного фонда и лица, осуществляющего полномочия единоличного исполнительного органа наследственного фонда, в случае их выбытия, в том числе предусмотрено подназначение указанных лиц из определенного списка.\n\n5. Условия управления наследственным фондом должны включать в себя положения, указанные в пунктах 1 и 3 статьи 12320-5 настоящего Кодекса.\n\nУсловия управления наследственным фондом до направления нотариусом указанного в абзаце третьем пункта 1 настоящей статьи заявления доводятся им до сведения лиц, входящих в состав органов наследственного фонда, и могут быть раскрыты только выгодоприобретателям в соответствии с пунктом 5 статьи 12320-5 настоящего Кодекса, а также в предусмотренных законом случаях органам государственной власти и органам местного самоуправления.\n\n6. Единоличный исполнительный орган наследственного фонда обязан хранить устав наследственного фонда и внесенные в него изменения и дополнения, которые зарегистрированы в установленном порядке, решение об учреждении наследственного фонда, документы, подтверждающие права наследственного фонда на его имущество, документ, содержащий условия управления наследственным фондом, годовые отчеты, документы бухгалтерского учета, документы бухгалтерской (финансовой) отчетности, протоколы собраний коллегиальных органов наследственного фонда, отчеты оценщиков, заключения ревизионной комиссии (ревизора) наследственного фонда, аудитора наследственного фонда, государственных и муниципальных органов финансового контроля, судебные акты по спорам, связанным с управлением наследственным фондом, иные документы, предусмотренные настоящим Кодексом, уставом наследственного фонда и условиями управления наследственным фондом.\n\nУставом наследственного фонда может быть предусмотрено хранение документов, указанных в абзаце первом настоящего пункта, у нотариуса по правилам, предусмотренным законодательством о нотариате.\n\n2. Учреждения","article_title":"Статья 123.20-8. Создание наследственного фонда и управление им","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e154248b11e5683a562d64a70b82a501255f186486a2d96919b9843abc8dec83"},{"code_id":"GK_RF","article_number":"123.21","version_date":"1994-11-30","article_text":"1. Учреждением признается унитарная некоммерческая организация, созданная собственником для осуществления управленческих, социально-культурных или иных функций некоммерческого характера.\n\nУчредитель является собственником имущества созданного им учреждения. На имущество, закрепленное собственником за учреждением и приобретенное учреждением по иным основаниям, оно приобретает право оперативного управления в соответствии с настоящим Кодексом.\n\n2. Учреждение может быть создано гражданином или юридич\n\nеским лицом (частное учреждение) либо соответственно Российской Федерацией, субъектом Российской Федерации, муниципальным образованием (государственное учреждение, муниципальное учреждение).\n\nПри создании учреждения не допускается соучредительство нескольких лиц.\n\n3. Учреждение отвечает по своим обязательствам находящимися в его распоряжении денежными средствами, а в случаях, установленных законом, также иным имуществом. При недостаточности указанных денежных средств или имущества субсидиарную ответственность по обязательствам учреждения в случаях, предусмотренных пунктами 4 - 6 статьи 12322 и пунктом 2 статьи 12323 настоящего Кодекса, несет собственник соответствующего имущества.\n\n4. Учредитель учреждения назначает его руководителя, являющегося органом учреждения. В случаях и в порядке, которые предусмотрены законом, руководитель государственного или муниципального учреждения может избираться его коллегиальным органом и утверждаться его учредителем.\n\nПо решению учредителя в учреждении могут быть созданы коллегиальные органы, подотчетные учредителю. Компетенция коллегиальных органов учреждения, порядок их создания и принятия ими решений определяются законом и уставом учреждения.","article_title":"Статья 123.21. Основные положения об учреждениях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c77b00705ce4b524971389eec4bd4ee7ab985c475556466795703d903075cc6"},{"code_id":"GK_RF","article_number":"123.22","version_date":"1994-11-30","article_text":"1. Государственное или муниципальное учреждение может быть казенным, бюджетным или автономным учреждением.\n\n2. Порядок финансового обеспечения деятельности государственных и муниципальных учреждений определяется законом.\n\n3. Государственные и муниципальные учреждения не отвечают по обязательствам собственников своего имущества.\n\n4. Казенное учреждение отвечает по своим обязательствам находящимися в его распоряжении денежными средствами. При недостаточности денежных средств субсидиарную ответственность по обязательствам казенного учреждения несет собственник его имущества.\n\n5. Бюджетное учреждение отвечает по своим обязательствам всем находящимся у него на праве оперативного управления имуществом, в том числе приобретенным за счет доходов, полученных от приносящей доход деятельности, за исключением особо ценного движимого имущества, закрепленного за бюджетным учреждением собственником этого имущества или приобретенного бюджетным учреждением за счет средств, выделенных собственником его имущества, а также недвижимого имущества независимо от того, по каким основаниям оно поступило в оперативное управление бюджетного учреждения и за счет каких средств оно приобретено.\n\nПо обязательствам бюджетного учреждения, связанным с причинением вреда гражданам, при недостаточности имущества учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность несет собственник имущества бюджетного учреждения.\n\nВ случае ликвидации бюджетного учреждения при недостаточности имущества бюджетного учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность по обязательствам бюджетного учреждения, вытекающим из публичного договора, несет собственник имущества бюджетного учреждения. (Дополнение абзацем - Федеральный закон от 11.03.2024 № 48-ФЗ)\n\n6. Автономное учреждение отвечает по своим обязательствам всем находящимся у него на праве оперативного управления имуществом, за исключением недвижимого имущества и особо ценного движимого имущества, закрепленных за автономным учреждением собственником этого имущества или приобретенных автономным учреждением за счет средств, выделенных собственником его имущества.\n\nПо обязательствам автономного учреждения, связанным с причинением вреда гражданам, при недостаточности имущества учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность несет собственник имущества автономного учреждения.\n\nВ случае ликвидации автономного учреждения при недостаточности имущества автономного учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность по обязательствам автономного учреждения, вытекающим из публичного договора, несет собственник имущества автономного учреждения. (Дополнение абзацем - Федеральный закон от 11.03.2024 № 48-ФЗ)\n\nЕжегодно автономное учреждение обязано опубликовывать отчеты о своей деятельности и об использовании закрепленного за ним имущества.\n\n7. Государственное или муниципальное учреждение может быть преобразовано в некоммерческую организацию иных организационно-правовых форм в случаях, предусмотренных законом.\n\n8. Особенности правового положения государственных и муниципальных учреждений отдельных типов определяются законом.","article_title":"Статья 123.22. Государственное учреждение и муниципальное учреждение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7191aea6440779015b86106e405c64e2ce9fab7672797cb0d5c3702388548c8"},{"code_id":"GK_RF","article_number":"123.23","version_date":"1994-11-30","article_text":"1. Частное учреждение полностью или частично финансируется собственником его имущества.\n\n2. Частное учреждение отвечает по своим обязательствам находящимися в его распоряжении денежными средствами. При недостаточности указанных денежных средств субсидиарную ответственность по обязательствам частного учреждения несет собственник его имущества.\n\n3. Частное учреждение может быть преобразовано учредителем в автономную некоммерческую организацию или фонд.\n\n3. Автономные некоммерческие организации","article_title":"Статья 123.23. Частное учреждение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"abcaca968491f93efd19d42b3d4429a1d681191545f3d30a40da9444fe1833e5"},{"code_id":"GK_RF","article_number":"123.24","version_date":"1994-11-30","article_text":"1. Автономной некоммерческой организацией признается унитарная некоммерческая организация, не имеющая членства и созданная на основе имущественных взносов граждан и (или) юридических лиц в целях предоставления услуг в сферах образования, здравоохранения, культуры, науки и иных сферах некоммерческой деятельности.\n\nАвтономная некоммерческая организация может быть создана одним лицом (может иметь одного учредителя).\n\n2. Устав автономной некоммерческой организации должен содержать сведения о ее наименовании, включающем слова \"автономная некоммерческая организация\", месте нахождения, предмете и целях ее деятельности, составе, порядке образования и компетенции органов автономной некоммерческой организации, а также иные предусмотренные законом сведения.\n\n3. Имущество, переданное автономной некоммерческой организации ее учредителями, является собственностью автономной некоммерческой организации. Учредители автономной некоммерческой организации не сохраняют права на имущество, переданное ими в собственность этой организации.\n\nУчредители не отвечают по обязательствам созданной ими автономной некоммерческой организации, а она не отвечает по обязательствам своих учредителей.\n\n4. Учредители автономной некоммерческой организации могут пользоваться ее услугами только на равных условиях с другими лицами.\n\n5. Автономная некоммерческая организация вправе заниматься предпринимательской деятельностью, необходимой для достижения целей, ради которых она создана, и соответствующей этим целям, создавая для осуществления предпринимательской деятельности хозяйственные общества или участвуя в них.\n\n6. Лицо может по своему усмотрению выйти из состава учредителей автономной некоммерческой организации.\n\nПо решению учредителей автономной некоммерческой организации, принятому единогласно, в состав ее учредителей могут быть приняты новые лица.\n\n7. Автономная некоммерческая организация по решению своих учредителей может быть преобразована в фонд.\n\n8. В части, не урегулированной настоящим Кодексом, правовое положение автономных некоммерческих организаций, а также права и обязанности их учредителей устанавливаются законом.","article_title":"Статья 123.24. Основные положения об автономной некоммерческой организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"845466ed4206e5e20c904d2a41bc008e38badaed22d52574ae9bbb97a3a3f033"},{"code_id":"GK_RF","article_number":"123.25","version_date":"1994-11-30","article_text":"1. Управление деятельностью автономной некоммерческой организации осуществляют ее учредители в порядке, установленном ее уставом, утвержденным ее учредителями.\n\n2. По решению учредителей (учредителя) автономной некоммерческой организации в ней может быть создан постоянно действующий коллегиальный орган (органы), компетенция которого устанавливается уставом автономной некоммерческой организации.\n\n3. Учредители (учредитель) автономной некоммерческой организации назначают единоличный исполнительный орган автономной некоммерческой организации (председателя, генерального директора и т.п.). Единоличным исполнительным органом автономной некоммерческой организации может быть назначен один из ее учредителей-граждан.\n\n4. Религиозные организации","article_title":"Статья 123.25. Управление автономной некоммерческой организацией","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b97a70f84443e43ac5608c71de9741cf6abe12d61c175dc964c0beb87a28841"},{"code_id":"GK_RF","article_number":"123.26","version_date":"1994-11-30","article_text":"1. Религиозной организацией признается добровольное объединение постоянно и на законных основаниях проживающих на территории Российской Федерации граждан Российской Федерации или иных лиц, образованное ими в целях совместного исповедания и распространения веры и зарегистрированное в установленном законом порядке в качестве юридического лица (местная религиозная организация), объединение этих организаций (централизованная религиозная организация), а также созданная указанным объединением в соответствии с законом о свободе совести и о религиозных объединениях в целях совместного исповедания и распространения веры организация и (или) созданный указанным объединением руководящий или координирующий орган.\n\n2. Гражданско-правовое положение религиозных организаций определяется настоящим Кодексом и законом о свободе совести и о религиозных объединениях. Положения настоящего Кодекса применяются к религиозным организациям, если иное не установлено законом о свободе совести и о религиозных объединениях и другими законами.\n\nРелигиозные организации действуют в соответствии со своими уставами и внутренними установлениями, не противоречащими закону.\n\nПорядок образования органов религиозной организации и их компетенция, порядок принятия решений этими органами, а также отношения между религиозной организацией и лицами, входящими в состав ее органов, определяются в соответствии с законом о свободе совести и о религиозных объединениях уставом и внутренними установлениями религиозной организации.\n\n(Пункт в редакции Федерального закона от 06.04.2015 № 80-ФЗ)\n\n3. Религиозная организация не может быть преобразована в юридическое лицо другой организационно-правовой формы.","article_title":"Статья 123.26. Основные положения о религиозных организациях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b021a0d800de59d09ffb3078544435ebe1918ecc650c18e4bd41de428eb617b"},{"code_id":"GK_RF","article_number":"123.27","version_date":"1994-11-30","article_text":"1. Местная религиозная организация создается в соответствии с законом о свободе совести и о религиозных объединениях не менее чем десятью гражданами-учредителями, централизованная религиозная организация - не менее чем тремя местными религиозными организациями или другой централизованной религиозной организацией.\n\n2. Учредительным документом религиозной организации является устав, утвержденный ее учредителями или централизованной религиозной организацией.\n\nУстав религиозной организации должен содержать сведения о ее виде, наименовании и месте нахождения, предмете и целях ее деятельности, составе, компетенции ее органов и порядке принятия ими решений, об источниках образования ее имущества, о направлениях его использования и порядке распределения имущества, остающегося после ее ликвидации, а также иные сведения, предусмотренные законом о свободе совести и о религиозных объединениях.\n\n3. Учредитель (учредители) религиозной организации может выполнять функции органа управления или членов коллегиального органа управления данной религиозной организации в порядке, установленном в соответствии с законом о свободе совести и о религиозных объединениях уставом религиозной организации и внутренними установлениями.","article_title":"Статья 123.27. Учредители и устав религиозной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ce30545f535a9b432f45d53a88fdfe4c6f366817a4023ce26f8e2c13949b232"},{"code_id":"GK_RF","article_number":"123.28","version_date":"1994-11-30","article_text":"1. Религиозные организации являются собственниками принадлежащего им имущества, в том числе имущества, приобретенного или созданного ими за счет собственных средств, а также пожертвованного религиозным организациям или приобретенного ими по иным предусмотренным законом основаниям.\n\n2. На принадлежащее религиозным организациям имущество богослужебного назначения не может быть обращено взыскание по требованиям их кредиторов. Перечень такого имущества определяется в порядке, установленном законом о свободе совести и о религиозных объединениях.\n\n3. Учредители религиозной организации не сохраняют имущественные права на имущество, переданное ими этой организации в собственность.\n\n4. Учредители религиозных организаций не отвечают по обязательствам этих организаций, а эти организации не отвечают по обязательствам своих учредителей.","article_title":"Статья 123.28. Имущество религиозной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b35a8b64c2a4701fa15ff707600ee479da76c18968b7358be4bdb13bc0ec9cb2"},{"code_id":"GK_RF","article_number":"123.3","version_date":"1994-11-30","article_text":"1. В течение трех месяцев после утверждения ежегодного баланса члены потребительского кооператива обязаны покрыть образовавшиеся убытки путем внесения дополнительных взносов. В случае невыполнения этой обязанности кооператив может быть ликвидирован в судебном порядке по требованию кредиторов.\n\n2. Члены потребительского кооператива солидарно несут субсидиарную ответственность по его обязательствам в пределах невнесенной части дополнительного взноса каждого из членов кооператива.\n\n3. Общественные организации","article_title":"Статья 123.3. Обязанность членов потребительского кооператива по внесению дополнительных взносов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a8ac2e6c977c38c732698e149ae70dc91fb1e04fbcdce3e18595c9a0d0bdd6b"},{"code_id":"GK_RF","article_number":"123.4","version_date":"1994-11-30","article_text":"1. Общественными организациями признаются добровольные объединения граждан, объединившихся в установленном законом порядке на основе общности их интересов для удовлетворения духовных или иных нематериальных потребностей, для представления и защиты общих интересов и достижения иных не противоречащих закону целей.\n\n2. Общественная организация является собственником своего имущества. Ее участники (члены) не сохраняют имущественные права на переданное ими в собственность организации имущество, в том числе на членские взносы.\n\nУчастники (члены) общественной организации не отвечают по обязательствам организации, в которой участвуют в качестве членов, а организация не отвечает по обязательствам своих членов.\n\n3. Общественные организации могут объединяться в ассоциации (союзы) в порядке, установленном настоящим Кодексом.","article_title":"Статья 123.4. Основные положения об общественных организациях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02d9e078fd41933dbad265440c14a61587f828c787b1db70801880c0395e0d2c"},{"code_id":"GK_RF","article_number":"123.5","version_date":"1994-11-30","article_text":"1. Количество учредителей общественной организации не может быть менее трех.\n\n2. Устав общественной организации должен содержать сведения о ее наименовании и месте нахождения, предмете и целях ее деятельности, а также условия о порядке вступления (принятия) в общественную организацию и выхода из нее, составе и компетенции ее органов и порядке принятия ими решений, в том числе по вопросам, решения по которым принимаются единогласно или квалифицированным большинством голосов, об имущественных правах и обязанностях участника (члена) организации и о порядке распределения имущества, оставшегося после ликвидации организации.","article_title":"Статья 123.5. Учредители и устав общественной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22e215c2644528b82e6ccebd92cdef7e8527538e57f19ecd3b50666ea6708bf4"},{"code_id":"GK_RF","article_number":"123.6","version_date":"1994-11-30","article_text":"1. Участник (член) общественной организации осуществляет корпоративные права, предусмотренные пунктом 1 статьи 652 настоящего Кодекса, в порядке, установленном уставом организации. Он также вправе на равных началах с другими участниками (членами) организации безвозмездно пользоваться оказываемыми ею услугами.\n\n2. Участник (член) общественной организации наряду с обязанностями, предусмотренными для участников корпорации пунктом 4 статьи 652 настоящего Кодекса, также несет обязанность уплачивать предусмотренные ее уставом членские и иные имущественные взносы.\n\nУчастник (член) общественной организации по своему усмотрению в любое время вправе выйти из организации, в которой он участвует.\n\n3. Членство в общественной организации неотчуждаемо. Осуществление прав участника (члена) общественной организации не может быть передано другому лицу.","article_title":"Статья 123.6. Права и обязанности участника (члена) общественной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"faeaa338315ebfc0250e9b6533c36e2ca60f569ac847da2f93308b5852ee2345"},{"code_id":"GK_RF","article_number":"123.7","version_date":"1994-11-30","article_text":"1. К исключительной компетенции высшего органа общественной организации наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относится также принятие решений о размере и порядке уплаты ее участниками (членами) членских и иных имущественных взносов.\n\n2. В общественной организации образуется единоличный исполнительный орган (председатель, президент и т.п.) и могут образовываться постоянно действующие коллегиальные исполнительные органы (совет, правление, президиум и т.п.).\n\nПо решению общего собрания членов общественной организации полномочия ее органа могут быть досрочно прекращены в случаях грубого нарушения этим органом своих обязанностей, обнаружившейся неспособности к надлежащему ведению дел или при наличии иных серьезных оснований.\n\n31. Общественные движения\n\n(Дополнение подпараграфом - Федеральный закон от 23.05.2015 № 133-ФЗ)","article_title":"Статья 123.7. Особенности управления в общественной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea8b5203b89522609dd237a181c39fefb5b5087d3dd9101c8d35aebac9caf68d"},{"code_id":"GK_RF","article_number":"123.7-1","version_date":"1994-11-30","article_text":"1. Общественным движением является состоящее из участников общественное объединение, преследующее социальные, политические и иные общественно полезные цели, поддерживаемые участниками общественного движения.\n\n2. Положения настоящего Кодекса о некоммерческих организациях применяются к общественным движениям, если иное не предусмотрено Федеральным законом от 19 мая 1995 года № 82-ФЗ \"Об общественных объединениях\".","article_title":"Статья 123.7-1. Общественные движения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ccae61cd8a941466011470278626bda35f37252409f7e9358682ff0f90dbd28"},{"code_id":"GK_RF","article_number":"123.8","version_date":"1994-11-30","article_text":"1. Ассоциацией (союзом) признается объединение юридических лиц и (или) граждан, основанное на добровольном или в установленных законом случаях на обязательном членстве и созданное для представления и защиты общих, в том числе профессиональных, интересов, для достижения общественно полезных целей, а также иных не противоречащих закону и имеющих некоммерческий характер целей.\n\nВ организационно-правовой форме ассоциации (союза) создаются, в частности, объединения лиц, имеющие целями координацию их предпринимательской деятельности, представление и защиту общих имущественных интересов, профессиональные объединения граждан, не имеющие целью защиту трудовых прав и интересов своих членов, профессиональные объединения граждан, не связанные с их участием в трудовых отношениях (объединения оценщиков, лиц творческих профессий и другие), саморегулируемые организации и их объединения. (В редакции федеральных законов от 13.07.2015 № 268-ФЗ; от 07.02.2017 № 12-ФЗ)\n\n2. Ассоциации (союзы) могут иметь гражданские права и нести гражданские обязанности, соответствующие целям их создания и деятельности, предусмотренным уставами таких ассоциаций (союзов).\n\n3. Ассоциация (союз) является собственником своего имущества. Ассоциация (союз) отвечает по своим обязательствам всем своим имуществом, если иное не предусмотрено законом в отношении ассоциаций (союзов) отдельных видов.\n\nАссоциация (союз) не отвечает по обязательствам своих членов, если иное не предусмотрено законом.\n\nЧлены ассоциации (союза) не отвечают по ее обязательствам, за исключением случаев, если законом или уставом ассоциации (союза) предусмотрена субсидиарная ответственность ее членов.","article_title":"Статья 123.8. Основные положения об ассоциации (союзе)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e9b437a6d1200e00fadae2fef8a85b1a891b6d07ea23a00902b482a80ccae9c4"},{"code_id":"GK_RF","article_number":"123.9","version_date":"1994-11-30","article_text":"1. Число учредителей ассоциации (союза) не может быть менее двух. Законами, устанавливающими особенности правового положения ассоциаций (союзов) отдельных видов, могут быть установлены иные требования к минимальному числу учредителей таких ассоциаций (союзов).\n\n2. Устав ассоциации (союза) должен содержать сведения о ее наименовании и месте нахождения, предмете и целях ее деятельности, условия о порядке вступления (принятия) членов в ассоциацию (союз) и выхода из нее, сведения о составе и компетенции органов ассоциации (союза) и порядке принятия ими решений, в том числе по вопросам, решения по которым принимаются единогласно или квалифицированным большинством голосов, об имущественных правах и обязанностях членов ассоциации (союза), о порядке распределения имущества, оставшегося после ликвидации ассоциации (союза).","article_title":"Статья 123.9. Учредители ассоциации (союза) и устав ассоциации (союза)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69a86466e20766a0d7239685f3eeb17070a7463bb7394ac7a3c2a232b24a2adc"},{"code_id":"GK_RF","article_number":"124","version_date":"1994-11-30","article_text":"1. Российская Федерация, субъекты Российской Федерации: республики, края, области, города федерального значения, автономная область, автономные округа, а также городские, сельские поселения и другие муниципальные образования выступают в отношениях, регулируемых гражданским законодательством, на равных началах с иными участниками этих отношений - гражданами и юридическими лицами.\n\n2. К субъектам гражданского права, указанным в пункте 1 настоящей статьи, применяются нормы, определяющие участие юридических лиц в отношениях, регулируемых гражданским законодательством, если иное не вытекает из закона или особенностей данных субъектов.","article_title":"Статья 124. Российская Федерация, субъекты Российской Федерации, муниципальные образования - субъекты гражданского права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"823a4d4c4f3fee89f2c404a281b68ee3dad50cb3511890bc4f85444bd985a2f1"},{"code_id":"GK_RF","article_number":"125","version_date":"1994-11-30","article_text":"1. От имени Российской Федерации и субъектов Российской Федерации могут своими действиями приобретать и осуществлять имущественные и личные неимущественные права и обязанности, выступать в суде органы государственной власти в рамках их компетенции, установленной актами, определяющими статус этих органов.\n\n2. От имени муниципальных образований своими действиями могут приобретать и осуществлять права и обязанности, указанные в пункте 1 настоящей статьи, органы местного самоуправления в рамках их компетенции, установленной актами, определяющими статус этих органов.\n\n3. В случаях и в порядке, предусмотренных федеральными законами, указами Президента Российской Федерации и постановлениями Правительства Российской Федерации, нормативными актами субъектов Российской Федерации и муниципальных образований, по их специальному поручению от их имени могут выступать государственные органы, органы местного самоуправления, а также юридические лица и граждане.","article_title":"Статья 125. Порядок участия Российской Федерации, субъектов Российской Федерации, муниципальных образований в отношениях, регулируемых гражданским законодательством","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6122095a7af4384fee5d05ce627782a8473449f7f9503da39a0aebfa58c8852d"},{"code_id":"GK_RF","article_number":"126","version_date":"1994-11-30","article_text":"1. Российская Федерация, субъект Российской Федерации, муниципальное образование отвечают по своим обязательствам принадлежащим им на праве собственности имуществом, кроме имущества, которое закреплено за созданными ими юридическими лицами на праве хозяйственного ведения или оперативного управления, а также имущества, которое может находиться только в государственной или муниципальной собственности.\n\nОбращение взыскания на землю и другие природные ресурсы, находящиеся в государственной или муниципальной собственности, допускается в случаях, предусмотренных законом.\n\n2. Юридические лица, созданные Российской Федерацией, субъектами Российской Федерации, муниципальными образованиями, не отвечают по их обязательствам.\n\n3. Российская Федерация, субъекты Российской Федерации, муниципальные образования не отвечают по обязательствам созданных ими юридических лиц, кроме случаев, предусмотренных законом.\n\n4. Российская Федерация не отвечает по обязательствам субъектов Российской Федерации и муниципальных образований.\n\n5. Субъекты Российской Федерации, муниципальные образования не отвечают по обязательствам друг друга, а также по обязательствам Российской Федерации.\n\n6. Правила пунктов 2 - 5 настоящей статьи не распространяются на случаи, когда Российская Федерация приняла на себя гарантию (поручительство) по обязательствам субъекта Российской Федерации, муниципального образования или юридического лица либо указанные субъекты приняли на себя гарантию (поручительство) по обязательствам Российской Федерации.","article_title":"Статья 126. Ответственность по обязательствам Российской Федерации, субъекта Российской Федерации, муниципального образования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e30a58ae70e0e9978ebf9cc3bc7ff2f322e94dcf163846ec1a89f417188fcb3"},{"code_id":"GK_RF","article_number":"127","version_date":"1994-11-30","article_text":"Особенности ответственности Российской Федерации и субъектов Российской Федерации в отношениях, регулируемых гражданским законодательством, с участием иностранных юридических лиц, граждан и государств определяются законом об иммунитете государства и его собственности.","article_title":"Статья 127. Особенности ответственности Российской Федерации и субъектов Российской Федерации в отношениях, регулируемых гражданским законодательством, с участием иностранных юридических лиц, граждан и государств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ade5c7296aa7501134bbc2382af6b45b3052f134e29f6f9a6f09c5364578ea9"},{"code_id":"GK_RF","article_number":"128","version_date":"1994-11-30","article_text":"К объектам гражданских прав относятся вещи (включая наличные деньги и документарные ценные бумаги), иное имущество, в том числе имущественные права (включая безналичные денежные средства, в том числе цифровые рубли, бездокументарные ценные бумаги, цифровые права); результаты работ и оказание услуг; охраняемые результаты интеллектуальной деятельности и приравненные к ним средства индивидуализации (интеллектуальная собственность); нематериальные блага. (В редакции  федеральных законов от 18.03.2019 № 34-ФЗ, от 24.07.2023 № 339-ФЗ)\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 128. Объекты гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be8f4ce6bfb94027177018bfe5d8d60416b73d301afbc6ef3154d771fe86c126"},{"code_id":"GK_RF","article_number":"13","version_date":"1994-11-30","article_text":"Ненормативный акт государственного органа или органа местного самоуправления, а в случаях, предусмотренных законом, также нормативный акт, не соответствующие закону или иным правовым актам и нарушающие гражданские права и охраняемые законом интересы гражданина или юридического лица, могут быть признаны судом недействительными.\n\nВ случае признания судом акта недействительным нарушенное право подлежит восстановлению либо защите иными способами, предусмотренными статьей 12 настоящего Кодекса.","article_title":"Статья 13. Признание недействительным акта государственного органа или органа местного самоуправления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44948e57e29c13246c406a0e3ef5ab98c9f0916dd1767ebfdf3f006600d2f276"},{"code_id":"GK_RF","article_number":"130","version_date":"1994-11-30","article_text":"К недвижимым вещам относятся также подлежащие государственной регистрации воздушные и морские суда, суда внутреннего плавания. Законом к недвижимым вещам может быть отнесено и иное имущество. (В редакции Федерального закона от 13.07.2015 № 216-ФЗ)\n\nК недвижимым вещам относятся жилые и нежилые помещения, а также предназначенные для размещения транспортных средств части зданий или сооружений (маши\n\nно-места), если границы таких помещений, частей зданий или сооружений описаны в установленном законодательством о государственном кадастровом учете порядке. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 315-ФЗ)","article_title":"Статья 130. Недвижимые и движимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d92b31c62ad8dda9d5a00ff683ee86462a9a5029180b8b0d0f82a7f33575522"},{"code_id":"GK_RF","article_number":"131","version_date":"1994-11-30","article_text":"Информация предоставляется в любом органе, осуществляющем регистрацию недвижимости, независимо от места совершения регистрации.","article_title":"Статья 131. Государственная регистрация недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d63586028a8b316fb71345f9cba616e031d2d4363fcabc793e5956c774cd3924"},{"code_id":"GK_RF","article_number":"132","version_date":"1994-11-30","article_text":"1. Предприятием как объектом прав признается имущественный комплекс, используемый для осуществления предпринимательской деятельности.\n\nПредприятие в целом как имущественный комплекс признается недвижимостью.\n\n2. Предприятие в целом или его часть могут быть объектом купли-продажи, залога, аренды и других сделок, связанных с установлением, изменением и прекращением вещных прав.\n\nВ состав предприятия как имущественного комплекса входят все виды имущества, предназначенные для его деятельности, включая земельные участки, здания, сооружения, оборудование, инвентарь, сырье, продукцию, права требования, долги, а также права на обозначения, индивидуализирующие предприятие, его продукцию, работы и услуги (коммерческое обозначение, товарные знаки, знаки обслуживания), и другие исключительные права, если иное не предусмотрено законом или договором. (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 132. Предприятие","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5539f7f2ad6f43061ec669318e08d405ac8d5da8d3c32d10c132f4235fb93d0d"},{"code_id":"GK_RF","article_number":"133","version_date":"1994-11-30","article_text":"1. Вещь, раздел которой в натуре невозможен без разрушения, повреждения вещи или изменения ее назначения и которая выступает в обороте как единый объект вещных прав, является неделимой вещью и в том случае, если она имеет составные части.\n\n2. Замена одних составных частей неделимой вещи другими составными частями не влечет возникновения иной вещи, если при этом существенные свойства вещи сохраняются.\n\n3. Взыскание может быть обращено на неделимую вещь только в целом, если законом или судебным актом не установлена возможность выделения из вещи ее составной части, в том числе в целях продажи ее отдельно.\n\n4. Отношения по поводу долей в праве собственности на неделимую вещь регулируются правилами главы 16, статьи 1168 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 133. Неделимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40d994b6ddf70af782eb99feee5d6bdf55edc7ac7d1324ab857112f3e5ddbcff"},{"code_id":"GK_RF","article_number":"133.1","version_date":"1994-11-30","article_text":"Недвижимой вещью, участвующей в обороте как единый объект, может являться единый недвижимый комплекс - совокупность объединенных единым назначением зданий, сооружений и иных вещей, неразрывно связанных физически или технологически, в том числе линейных объектов (железные дороги, линии электропередачи, трубопроводы и другие), либо расположенных на одном земельном участке, если в едином государственном реестре прав на недвижимое имущество зарегистрировано право собственности на совокупность указанных объектов в целом как одну недвижимую вещь.\n\nК единым недвижимым комплексам применяются правила о неделимых вещах.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 142-ФЗ)","article_title":"Статья 133.1. Единый недвижимый комплекс","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04cd42cd450adc220c4d5d0058bf54d250d81901648f4c3c161c0b5ef54e21ad"},{"code_id":"GK_RF","article_number":"134","version_date":"1994-11-30","article_text":"Если различные вещи соединены таким образом, который предполагает их использование по общему назначению (сложная вещь), то действие сделки, совершенной по поводу сложной вещи, распространяется на все входящие в нее вещи, поскольку условиями сделки не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 134. Сложные вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"282f6bcee635957b1d351fe75bcc2aaec749e2f117611481d5a762b55fc27d28"},{"code_id":"GK_RF","article_number":"135","version_date":"1994-11-30","article_text":"Вещь, предназначенная для обслуживания другой, главной, вещи и связанная с ней общим назначением (принадлежность), следует судьбе главной вещи, если договором не предусмотрено иное.","article_title":"Статья 135. Главная вещь и принадлежность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c17a0cdc97eefcdf6f6d85773eab4af87c0fa9f0a2485f8f2f91ba528c50df7"},{"code_id":"GK_RF","article_number":"136","version_date":"1994-11-30","article_text":"Плоды, продукция, доходы, полученные в результате использования вещи, независимо от того, кто использует такую вещь, принадлежат собственнику вещи, если иное не предусмотрено законом, иными правовыми актами, договором или не вытекает из существа отношений.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 136. Плоды, продукция и доходы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b48e1990980fcb9ff983fc0b3f02f2db6bfb311cf74d4c43814c01e51c867cd"},{"code_id":"GK_RF","article_number":"137","version_date":"1994-11-30","article_text":"К животным применяются общие правила об имуществе постольку, поскольку законом или иными правовыми актами не установлено иное.\n\nПри осуществлении прав не допускается жестокое обращение с животными, противоречащее принципам гуманности.","article_title":"Статья 137. Животные","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4dc12fd3d9418fd95b231a375b8e8d36c3df7fcbe3c2979b4cc3c21af7900907"},{"code_id":"GK_RF","article_number":"138","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 18.12.2006 № 231-ФЗ)","article_title":"Статья 138. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45740e332c27a9cd0706f6f2abe7683e9b043ff9593181185e457091501a104d"},{"code_id":"GK_RF","article_number":"139","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 18.12.2006 № 231-ФЗ)","article_title":"Статья 139. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45740e332c27a9cd0706f6f2abe7683e9b043ff9593181185e457091501a104d"},{"code_id":"GK_RF","article_number":"14","version_date":"1994-11-30","article_text":"Допускается самозащита гражданских прав.\n\nСпособы самозащиты должны быть соразмерны нарушению и не выходить за пределы действий, необходимых для его пресечения.","article_title":"Статья 14. Самозащита гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8743447a19ba75dbb9fda10a1ff3e930a1a8f8cbee6a5593b4833dede5d39eb"},{"code_id":"GK_RF","article_number":"140","version_date":"1994-11-30","article_text":"1. Рубль является законным платежным средством, обязательным к приему по нарицательной стоимости на всей территории Российской Федерации.\n\nПлатежи на территории Российской Федерации осуществляются путем наличных и безналичных расчетов, включая расчеты цифровыми рублями. (В редакции  Федерального закона от 24.07.2023 № 339-ФЗ)\n\n2. Случаи, порядок и условия использования иностранной валюты на территории Российской Федерации определяются законом или в установленном им порядке.","article_title":"Статья 140. Деньги (валюта)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb7f0979a7ee583dce391341c61d3c3e084c9b0b029c43ca67fc5083243bb5d7"},{"code_id":"GK_RF","article_number":"141","version_date":"1994-11-30","article_text":"Виды имущества, признаваемого валютными ценностями, и порядок совершения сделок с ними определяются законом о валютном регулировании и валютном контроле.\n\nПрава на валютные ценности защищаются в Российской Федерации на общих основаниях. (В редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 141. Валютные ценности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89ecc0d90e218a655d42e6ff3aef788335587c2cd4aa75a367546f383d8eac55"},{"code_id":"GK_RF","article_number":"141.1","version_date":"1994-11-30","article_text":"1. Цифровыми правами признаются названные в таком качестве в законе обязательственные и иные права, содержание и условия осуществления которых определяются в соответствии с правилами информационной системы, отвечающей установленным законом признакам. Осуществление, распоряжение, в том числе передача, залог, обременение цифрового права другими способами или ограничение распоряжения цифровым правом возможны только в информационной системе без обращения к третьему лицу.\n\n2. Если иное не предусмотрено законом, обладателем цифрового права признается лицо, которое в соответствии с правилами информационной системы имеет возможность распоряжаться этим правом. В случаях и по основаниям, которые предусмотрены законом, обладателем цифрового права признается иное лицо.\n\n3. Переход цифрового права на основании сделки не требует согласия лица, обязанного по такому цифровому праву.\n\n(Дополнение статьей - Федеральный закон от 18.03.2019 № 34-ФЗ)\n\n(Дополнение главой - Федеральный закон от 21.12.2021 № 430-ФЗ)","article_title":"Статья 141.1. Цифровые права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef0a3749a75d719fdf6f213c185c575f05f33d42b28f09b5eacd9029a9787d9f"},{"code_id":"GK_RF","article_number":"141.2","version_date":"1994-11-30","article_text":"1. Земельным участком признается часть поверхности земли, границы которой определены в порядке, установленном законом.\n\n2. Земельный участок является недвижимой вещью (статья 130).","article_title":"Статья 141.2. Земельный участок как недвижимая вещь","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8154d8e8d0f1524599d5e4cc227725d109c466b12acf3e46581818c4d6d9ea9d"},{"code_id":"GK_RF","article_number":"141.3","version_date":"1994-11-30","article_text":"1. Здания и сооружения являются недвижимыми вещами (статья 130). Здания и сооружения создаются в результате строительства.\n\n2. Здания и сооружения могут быть образованы в результате раздела недвижимой вещи (здания, сооружения, единого недвижимого комплекса) или в результате объединения нескольких недвижимых вещей (зданий, сооружений, всех помещений и машино-мест, расположенных в одном здании, сооружении).\n\n3. Изменение характеристик здания или сооружения не влечет образования новых здания или сооружения, если иное не установлено законом.","article_title":"Статья 141.3. Здания и сооружения как недвижимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0189cd1a73827ba3fc96440def20ae322c9844aa4a54b93573a5539b4b50e604"},{"code_id":"GK_RF","article_number":"141.4","version_date":"1994-11-30","article_text":"1. Помещением признается обособленная часть здания или сооружения, пригодная для постоянного проживания граждан (жилое помещение) либо для других целей, не связанных с проживанием граждан (нежилое помещение), и подходящая для использования в соответствующих целях.\n\n2. Помещения, предназначенные для обслуживания иных помещений в здании или сооружении, являются общим имуществом в таких здании или сооружении и не участвуют в обороте как самостоятельные недвижимые вещи, за исключением случая, предусмотренного пунктом 7 статьи 2875 настоящего Кодекса.\n\n3. Помещения, машино-места как недвижимые вещи могут быть образованы в том числе в результате раздела недвижимой вещи (здания, сооружения, в которых они образуются, помещения), объединения смежных недвижимых вещей (помещений, машино-мест) либо в результате реконструкции здания, сооружения, при проведении которой образуются помещения, машино-места как новые недвижимые вещи.\n\n4. В одном здании, сооружении может быть образовано не менее двух помещений и (или) машино-мест.\n\n5. При перепланировке помещений, машино-мест могут быть образованы иные помещения, машино-места путем объединения смежных помещений, машино-мест или раздела помещений, машино-мест. В остальных случаях осуществления перепланировки помещение, машино-место сохраняются как недвижимая вещь, в том числе в измененных границах.\n\n6. Образование помещений и машино-мест в объектах незавершенного строительства не допускается.\n\n7. Правила настоящей главы о помещениях подлежат применению к жилым помещениям, если иное не установлено Жилищным кодексом Российской Федерации.","article_title":"Статья 141.4. Помещения как недвижимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"643d2f9fca1706d6f9e8f9de9a9995dc6a93c19c1fc27e6766438de6c057c349"},{"code_id":"GK_RF","article_number":"141.5","version_date":"1994-11-30","article_text":"1. Законом могут быть установлены запреты или ограничения на образование отдельных видов недвижимых вещей либо условия, при соблюдении которых допускается образование таких недвижимых вещей.\n\n2. Обременения, установленные в отношении исходной недвижимой вещи, сохраняются в отношении всех образованных недвижимых вещей, если настоящим Кодексом или соглашением собственника исходной недвижимой вещи с лицом, в пользу которого установлено обременение, не определено иное.\n\n3. При разделе линейного объекта, в том числе при осуществлении которого не производится его реконструкция, могут быть образованы один или несколько линейных объектов, включая линейный объект, раздел которого осуществлен, с измененными параметрами.\n\n(Глава в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 141.5. Образование недвижимых вещей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a8d4facea3c573789034ba7786e4b27bea3f4a12bc89d2cbfa5559ce16ec0f5"},{"code_id":"GK_RF","article_number":"142","version_date":"1994-11-30","article_text":"1. Ценными бумагами являются документы, соответствующие установленным законом требованиям и удостоверяющие обязательственные и иные права, осуществление или передача которых возможны только при предъявлении таких документов (документарные ценные бумаги).\n\nЦенными бумагами признаются также обязательственные и иные права, которые закреплены в решении о выпуске или ином акте лица, выпустившего ценные бумаги в соответствии с требованиями закона, и осуществление и передача которых возможны только с соблюдением правил учета этих прав в соответствии со статьей 149 настоящего Кодекса (бездокументарные ценные бумаги).\n\n2. Ценными бумагами являются акция, вексель, закладная, инвестиционный пай паевого инвестиционного фонда, коносамент, облигация, чек и иные ценные бумаги, названные в таком качестве в законе или признанные таковыми в установленном законом порядке.\n\nВыпуск или выдача ценных бумаг подлежит государственной регистрации в случаях, установленных законом.","article_title":"Статья 142. Ценные бумаги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a12c60fd613dabfa809e0b8a8089ac94c9d42b9f7ec3d6196b6b11980bca26b1"},{"code_id":"GK_RF","article_number":"143","version_date":"1994-11-30","article_text":"1. Документарные ценные бумаги могут быть предъявительскими (ценными бумагами на предъявителя), ордерными и именными.\n\n2. Предъявительской является документарная ценная бумага, по которой лицом, уполномоченным требовать исполнения по ней, признается ее владелец.\n\n3. Ордерной является документарная ценная бумага, по которой лицом, уполномоченным требовать исполнения по ней, признается ее владелец, если ценная бумага выдана на его имя или перешла к нему от первоначального владельца по непрерывному ряду индоссаментов.\n\n4. Именной является документарная ценная бумага, по которой лицом, уполномоченным требовать исполнения по ней, признается одно из следующих указанных лиц:\n\n1) владелец ценной бумаги, указанный в качестве правообладателя в учетных записях, которые ведутся обязанным лицом или действующим по его поручению и имеющим соответствующую лицензию лицом. Законом может быть предусмотрена обязанность передачи такого учета лицу, имеющему соответствующую лицензию;\n\n2) владелец ценной бумаги, если ценная бумага была выдана на его имя или перешла к нему от первоначального владельца в порядке непрерывного ряда уступок требования (цессий) путем совершения на ней именных передаточных надписей или в иной форме в соответствии с правилами, установленными для уступки требования (цессии).\n\n5. Выпуск или выдача предъявительских ценных бумаг допускается в случаях, установленных законом.\n\nВозможность выпуска или выдачи определенных документарных ценных бумаг в качестве именных либо ордерных может быть исключена законом.\n\n6. Если иное не установлено настоящим Кодексом, законом или не вытекает из особенностей фиксации прав на бездокументарные ценные бумаги, к таким ценным бумагам применяются правила об именных документарных ценных бумагах, правообладатель которых определяется в соответствии с учетными записями.","article_title":"Статья 143. Виды ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26daeea7a3f0c3b483b2d7afe5f6cadfeabdd214db9d81257ef4caf37adb5456"},{"code_id":"GK_RF","article_number":"143.1","version_date":"1994-11-30","article_text":"1. Обязательные реквизиты, требования к форме документарной ценной бумаги и другие требования к документарной ценной бумаге определяются законом или в установленном им порядке.\n\n2. При отсутствии в документе обязательных реквизитов документарной ценной бумаги, несоответствии его установленной форме и другим требованиям документ не является ценной бумагой, но сохраняет значение письменного доказательства.","article_title":"Статья 143.1. Требования к документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"209c3b2d12bd5b073798969e9ea244181ef1b17236d615c40f7a3fccefe4b450"},{"code_id":"GK_RF","article_number":"144","version_date":"1994-11-30","article_text":"1. Надлежащим исполнением по документарной ценной бумаге признается исполнение лицу, определенному пунктами 2 - 4 статьи 143 настоящего Кодекса (владельцу ценной бумаги).\n\n2. Если ответственное за исполнение по документарной ценной бумаге лицо знало, что владелец ценной бумаги, которому произведено исполнение, не является надлежащим обладателем права на ценную бумагу, оно обязано возместить убытки, причиненные обладателю права на ценную бумагу.","article_title":"Статья 144. Исполнение по документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4fb7a8adc4514a73b47253c5afb644fcd01b23b85b83153a9f943892d43f5a95"},{"code_id":"GK_RF","article_number":"145","version_date":"1994-11-30","article_text":"1. Лицо, ответственное за исполнение по документарной ценной бумаге, вправе выдвигать против требований владельца ценной бумаги только те возражения, которые вытекают из ценной бумаги или основаны на отношениях между этими лицами.\n\nЛицо, составившее документарную ценную бумагу, отвечает по ценной бумаге и в случае, если документ поступил в обращение помимо его воли.\n\nПредусмотренные настоящим пунктом правила об ограничении возражений не применяются в случае, если владелец ценной бумаги в момент ее приобретения знал или должен был знать об отсутствии основания возникновения прав, удостоверенных ценной бумагой, в том числе о недействительности такого основания, либо об отсутствии прав предшествующих владельцев ценной бумаги, в том числе о недействительности основания их возникновения, а также в случае, если владелец ценной бумаги не является ее добросовестным приобретателем (статья 1471).\n\n2. Лица, ответственные за исполнение по ордерной ценной бумаге, не вправе ссылаться на возражения других лиц, ответственных за исполнение по данной ценной бумаге.\n\n3. Против требования об исполнении по документарной ценной бумаге лицо, указанное в качестве ответственного за исполнение по ней, может выдвинуть возражения, связанные с подделкой такой ценной бумаги или с оспариванием факта подписания им ценной бумаги (подлог ценной бумаги).","article_title":"Статья 145. Возражения по документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7997f663b08ef56ea54f67aa7b9f362de8396c8a8ce9a9f7affbff5d1d6f56dd"},{"code_id":"GK_RF","article_number":"146","version_date":"1994-11-30","article_text":"1. С переходом права на документарную ценную бумагу переходят все удостоверенные ею права в совокупности.\n\n2. Права, удостоверенные предъявительской ценной бумагой, передаются приобретателю путем вручения ему ценной бумаги лицом, совершившим ее отчуждение.\n\nПрава, удостоверенные предъявительской ценной бумагой, могут перейти к другому лицу независимо от ее вручения в случаях и по основаниям, которые установлены законом.\n\n3. Права, удостоверенные ордерной ценной бумагой, передаются приобретателю путем ее вручения с совершением на ней передаточной надписи - индоссамента. Если иное не предусмотрено настоящим Кодексом или законом, к передаче ордерных ценных бумаг применяются установленные законом о переводном и простом векселе правила о передаче векселя.\n\n4. Права, удостоверенные именной документарной ценной бумагой, передаются приобретателю путем вручения ему ценной бумаги лицом, совершающим ее отчуждение, с совершением на ней именной передаточной надписи или в иной форме в соответствии с правилами, установленными для уступки требования (цессии).\n\nНормы параграфа 1 главы 24 настоящего Кодекса применяются к передаче прав, удостоверенных именными документарными ценными бумагами, в порядке уступки требования (цессии), если иное не установлено правилами настоящей главы, иным законом или не вытекает из существа соответствующей ценной бумаги.\n\n5. В случае неисполнения обязательства передать ордерную или именную документарную ценную бумагу приобретатель вправе требовать ее изъятия у лица, во владении которого она находится, за исключением случаев, если на ценной бумаге учинены индоссамент или передаточная надпись лица, совершившего отчуждение, по которым права переданы иному лицу.\n\n6. В случае неисполнения обязательства по совершению индоссамента или передаточной надписи на ордерной или именной документарной ценной бумаге переход прав на ордерную или именную документарную ценную бумагу осуществляется по требованию приобретателя на основании решения суда путем совершения лицом, осуществляющим исполнение судебного решения, надписи на ценной бумаге, которая имеет силу индоссамента или передаточной надписи.\n\n7. Переход прав, удостоверенных ордерной или именной ценной бумагой, к другому лицу по основаниям иным, чем передача по договору, осуществляется путем приобретения права на ценную бумагу в случаях и по основаниям, которые установлены законом.\n\n8. Переход прав\n\nна ордерные или именные ценные бумаги подтверждается:\n\n1) при наследовании - отметкой нотариуса на самой ценной бумаге, которая имеет силу индоссамента или передаточной надписи предшествующего правообладателя;\n\n2) при реализации таких ценных бумаг в случае обращения на них взыскания - отметкой лица, уполномоченного на реализацию имущества владельца таких ценных бумаг;\n\n3) в иных случаях - на основании решения суда отметкой лица, осуществляющего исполнение судебного решения.\n\n9. При учете прав на именную документарную ценную бумагу права переходят к лицу, указанному в ценной бумаге, в момент внесения в учетные записи отметки о переходе прав. Отметка вносится на основании передаточного акта, совершенного сторонами в присутствии лица, осуществляющего учет в соответствии с пунктом 4 статьи 143 настоящего Кодекса, или на основании нотариально удостоверенного передаточного акта, предъявленного лицу, осуществляющему учет, одной из сторон.\n\n10. При уклонении лица, осуществляющего учет в соответствии с пунктом 4 статьи 143 настоящего Кодекса, от внесения в учетные записи отметки о переходе прав лицо, на имя которого совершен передаточный акт, может требовать в судебном порядке внесения соответствующей отметки в учетные записи.","article_title":"Статья 146. Переход прав, удостоверенных документарными ценными бумагами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5bcc4be638cf306716ad0fa789fb3b7d6fc76361430cf07b4c92df2fad15b7ed"},{"code_id":"GK_RF","article_number":"147","version_date":"1994-11-30","article_text":"1. Лицо, передавшее документарную ценную бумагу, несет ответственность за недействительность прав, удостоверенных ценной бумагой, если иное не установлено законом.\n\nЛицо, передавшее документарную ценную бумагу, несет ответственность за исполнение обязательства по ней при наличии соответствующей оговорки, а также в иных случаях, установленных законом.\n\n2. Владелец ценной бумаги, обнаруживший ее подлог или подделку, вправе потребовать от лица, передавшего ему ценную бумагу, исполнения обязательств по такой ценной бумаге и возмещения убытков.","article_title":"Статья 147. Ответственность за действительность прав, удостоверенных документарной ценной бумагой","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60a32533857150e7d2cc963c7e92c0dad01eb18f412ed9f2a342e06777b25766"},{"code_id":"GK_RF","article_number":"147.1","version_date":"1994-11-30","article_text":"1. Истребование документарных ценных бумаг из чужого незаконного владения осуществляется по правилам настоящего Кодекса об истребовании вещи из чужого незаконного владения с особенностями, предусмотренными настоящей статьей.\n\n2. Правом на истребование документарных ценных бумаг из чужого незаконного владения обладает лицо, которое на момент, когда ценные бумаги выбыли из его владения, являлось их законным владельцем.\n\n3. Не могут быть истребованы от добросовестного приобретателя предъявительские ценные бумаги независимо от того, какое право они удостоверяют, а также ордерные и именные ценные бумаги, удостоверяющие денежное требование.\n\n4. Правообладатель ценной бумаги, утративший ее в результате неправомерных действий, вправе потребовать от лица, которое приобрело ее у третьего лица, независимо от того, является ли такое третье лицо добросовестным или недобросовестным приобретателем, либо признается законным владельцем, возврата ценной бумаги или возмещения ее рыночной стоимости, если указанный приобретатель, от которого истребуется ценная бумага, своими обманными или другими незаконными действиями способствовал утрате прав законного владельца на ценную бумагу либо в качестве предшествующего владельца знал или должен был знать о наличии прав иных лиц на ценную бумагу.\n\n5. Лицо, которому документарная ценная бумага была возвращена из чужого незаконного владения, вправе потребовать от недобросовестного владельца возврата всего полученного по ценной бумаге, а также возмещения убытков; от добросовестного владельца - возврата всего полученного по ценной бумаге со времени, когда он узнал или должен был узнать о неправомерности владения ею либо получил из суда уведомление о предъявлении к нему иска об истребовании ценной бумаги.\n\nЕсли незаконный владелец воспользовался предоставленным ценной бумагой преимущественным правом приобретения какого-либо имущества, лицо, которому документарная ценная бумага была возвращена из чужого незаконного владения, вправе потребовать от такого владельца передачи ему приобретенного имущества при условии возмещения его стоимости по цене приобретения указанного имущества незаконным владельцем, а от недобросовестного владельца вправе потребовать также возмещения убытков.","article_title":"Статья 147.1. Особенности истребования документарных ценных бумаг от добросовестного приобретателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40f6741ac03ff40fe40469dfc8c1c5b5ebf59c9cc9568ace4bb63c17d7976747"}]$law7v006$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
